/* Couch To Front Office - draft-stage conversation pool (generated from theme-src/questions.dsl by build_questions.py).
   150 questions: 75 player-asks-GM, 75 GM-asks-player. Each has exactly 4 answers:
   strong (+1.4), moderate (+0.7), risky (0, personality-dependent), negative (-1.3) base swing, plus
   per-trait weights (scaled by (trait-50)/50) and context weights (rebuild/contend/thin/deep/chl/ncaa/euro/young/older/top/late). */
window.CTFO_DRAFT_QUESTIONS=[
{"id":"icetime-01","by":"player","cat":"icetime","q":"Will I get a real shot at camp this year?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Every job on this roster is open in September. Come take one.","traits":{"amb":0.6,"cmp":0.4},"ctx":{"rebuild":0.4,"thin":0.3}},{"type":"moderate","base":0.7,"text":"You'll get a real look in camp and in preseason games, and we'll be straight with you after that.","traits":{"coa":0.4,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Camp is a measuring stick. Most kids your age go back, and that's not a bad thing.","traits":{"pat":1.1,"amb":-1.1,"con":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"Not this year. There are veterans ahead of you and that's how it is.","traits":{"amb":-0.6,"con":-0.5},"ctx":{"contend":0.2}}]},
{"id":"icetime-02","by":"player","cat":"icetime","q":"Do you see me as a top-six guy down the road?","elig":{"pos":["F"]},"answers":[{"type":"strong","base":1.4,"text":"That's exactly why we took you where we did. We see top-six hands.","traits":{"amb":0.5,"con":0.5},"ctx":{"top":0.4}},{"type":"moderate","base":0.7,"text":"We think you can get there. It'll take work, but the tools are there.","traits":{"coa":0.5,"cmp":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"We see a guy who can play anywhere in the lineup. Where you land is up to you.","traits":{"cmp":1.0,"con":-0.6,"amb":-0.6},"ctx":{}},{"type":"negative","base":-1.3,"text":"Honestly, we project you more as a bottom-six energy guy.","traits":{"amb":-0.8,"con":-0.7},"ctx":{"late":0.3}}]},
{"id":"icetime-03","by":"player","cat":"icetime","q":"What kind of minutes would I be looking at as a rookie?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"If you make it, you'll play real minutes. We don't keep kids around to sit.","traits":{"amb":0.6,"con":0.3},"ctx":{"rebuild":0.3}},{"type":"moderate","base":0.7,"text":"Sheltered minutes to start, then more as you earn trust. That's how we build players.","traits":{"coa":0.5,"pat":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Ice time goes to whoever's playing best that week. Nobody gets anything handed to them.","traits":{"cmp":1.1,"pat":-0.4,"coa":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"You'd probably be the extra forward or the seventh D for a while.","traits":{"amb":-0.8,"con":-0.4},"ctx":{"contend":0.2,"deep":0.2}}]},
{"id":"icetime-04","by":"player","cat":"icetime","q":"Would I be a healthy scratch a lot if I made the team?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"No. If you're up with us, it's because you're in the lineup every night.","traits":{"amb":0.5,"con":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Some nights, maybe, but every scratch comes with a reason and a plan.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Probably. Watching from the press box teaches you a lot, and we'd want you up anyway.","traits":{"pat":1.0,"amb":-1.0,"cmp":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"We'd rather have you scratched with us than playing big minutes somewhere else.","traits":{"amb":-0.7,"con":-0.5,"coa":-0.2},"ctx":{}}]},
{"id":"icetime-05","by":"player","cat":"icetime","q":"Will I get time on the power play?","elig":{"pos":["F","D"]},"answers":[{"type":"strong","base":1.4,"text":"You've got power-play vision. We want that on our second unit as soon as you're ready.","traits":{"amb":0.6,"con":0.4},"ctx":{"thin":0.3}},{"type":"moderate","base":0.7,"text":"You'll get looks there in camp and in the AHL or wherever you play. We want to see it at our level.","traits":{"coa":0.4,"cmp":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Special teams are earned. Kill penalties first and see what happens.","traits":{"cmp":1.0,"coa":0.4,"amb":-0.8,"con":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"Our power play is set. That's not where we see you helping us.","traits":{"amb":-0.8,"con":-0.6},"ctx":{"contend":0.3,"deep":0.2}}]},
{"id":"icetime-06","by":"player","cat":"icetime","q":"Who would I be competing with for a spot?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Nobody you can't beat. The depth chart at your position is wide open.","traits":{"amb":0.5,"cmp":0.4},"ctx":{"thin":0.5,"rebuild":0.2}},{"type":"moderate","base":0.7,"text":"A couple of young guys and a veteran on a one-year deal. It's a fair fight.","traits":{"cmp":0.5,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Some good players. If that scares you, you're not the guy we think you are.","traits":{"cmp":1.2,"con":0.4,"pat":-0.4,"loy":-0.6},"ctx":{}},{"type":"negative","base":-1.3,"text":"Honestly, there are four or five guys ahead of you right now.","traits":{"amb":-0.7,"con":-0.5},"ctx":{"deep":0.3}}]},
{"id":"icetime-07","by":"player","cat":"icetime","q":"Is there a real path for a goalie my age here?","elig":{"pos":["G"]},"answers":[{"type":"strong","base":1.4,"text":"Yes. Our crease is going to need a starter in a few years and we want it to be you.","traits":{"amb":0.5,"loy":0.4},"ctx":{"thin":0.4}},{"type":"moderate","base":0.7,"text":"Goalies take time. We have a three-year plan for you with a goalie coach who's done it before.","traits":{"pat":0.6,"coa":0.5},"ctx":{}},{"type":"risky","base":0.0,"text":"Goalies are voodoo. You'll get your chance if you outplay the guys around you.","traits":{"cmp":1.1,"con":0.3,"pat":-0.3,"coa":-0.5},"ctx":{}},{"type":"negative","base":-1.3,"text":"We have our starter locked up long-term, so it's a long road.","traits":{"amb":-0.8,"con":-0.4},"ctx":{"deep":0.3,"contend":0.2}}]},
{"id":"icetime-08","by":"player","cat":"icetime","q":"Will you let me play my game, or do I have to change it?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"We drafted your game. We're not here to take the creativity out of you.","traits":{"con":0.6,"amb":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"We'll add to it, not take away from it. Details away from the puck, mostly.","traits":{"coa":0.6,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Every player changes when he turns pro. The ones who adapt fastest play the soonest.","traits":{"coa":1.0,"cmp":0.4,"con":-1.0},"ctx":{}},{"type":"negative","base":-1.3,"text":"You'll need to simplify a lot. What works in junior won't work here.","traits":{"con":-0.9,"amb":-0.4},"ctx":{"chl":0.2}}]},
{"id":"icetime-09","by":"player","cat":"icetime","q":"How many rookies actually made your team last year?","elig":{"role":["rebuild"]},"answers":[{"type":"strong","base":1.4,"text":"Three, and two of them played over seventy games. We give kids the keys.","traits":{"amb":0.6,"cmp":0.3},"ctx":{"rebuild":0.4}},{"type":"moderate","base":0.7,"text":"A couple. We're building around young players, so that number is going up.","traits":{"loy":0.4,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Enough. What matters is whether you're the one this year.","traits":{"cmp":1.0,"con":0.5,"pat":-0.5,"coa":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"Not many, to be honest. Most of our kids spent time in the AHL first.","traits":{"amb":-0.7,"con":-0.3},"ctx":{}}]},
{"id":"icetime-10","by":"gm","cat":"icetime","q":"If you had to pick: more ice time in the AHL or fewer minutes in the NHL?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's the answer of a guy who's going to make it. We'll build toward that.","traits":{"amb":0.6,"con":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Fair. We'll put you where you develop fastest and keep you in the loop on why.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Good, because you'll probably get neither if you don't come to camp in shape.","traits":{"cmp":1.0,"con":-0.6,"loy":-0.5},"ctx":{}},{"type":"negative","base":-1.3,"text":"Wrong answer, kid. Development minutes matter more than a jersey.","traits":{"amb":-0.8,"con":-0.7,"coa":0.2},"ctx":{}}],"reply":"Fewer minutes up top, every time. I want to be in the league."},
{"id":"icetime-11","by":"gm","cat":"icetime","q":"What does your ideal first pro season look like?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Then let's get you signed and get you ready for September.","traits":{"amb":0.7,"con":0.3},"ctx":{"rebuild":0.3}},{"type":"moderate","base":0.7,"text":"Good goal. We'll make sure you have every chance to make it happen.","traits":{"coa":0.4,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Ambitious. Most guys need a year to get there. Are you okay if that's you?","traits":{"pat":1.0,"amb":-1.0,"con":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"That's not realistic. Let's talk about a two-year plan instead.","traits":{"amb":-0.8,"con":-0.6},"ctx":{}}],"reply":"Making the team out of camp and never looking back."},
{"id":"pro-01","by":"gm","cat":"pro","q":"Are you ready to turn pro?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"We think so too. Let's get your contract done this summer and get you in the building.","traits":{"amb":0.6,"con":0.5},"ctx":{"older":0.4}},{"type":"moderate","base":0.7,"text":"We like that confidence. Let's talk with your family and your agent and find the right timing.","traits":{"fam":0.5,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Ready is a big word. Show us at development camp and we'll decide together.","traits":{"cmp":1.0,"coa":0.3,"con":-0.8,"amb":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"We'd rather you go back for another year. There's no rush on our end.","traits":{"amb":-0.9,"con":-0.5},"ctx":{"young":0.2}}],"reply":"I think I am. I've been ready for this my whole life."},
{"id":"pro-02","by":"player","cat":"pro","q":"Can I finish my college season first?","elig":{"league":["NCAA","NCAA_BOUND"]},"answers":[{"type":"strong","base":1.4,"text":"Of course. Finish school, win something, and we'll be waiting when you're done.","traits":{"col":0.9,"loy":0.4,"fam":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"We'd like you to consider leaving early, but we'll respect whatever you decide.","traits":{"col":0.4,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"We think you'd develop faster in the AHL. Your call, but the clock is ticking on your rights.","traits":{"amb":1.0,"col":-1.2,"pat":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"We drafted you to play for us, not for your school.","traits":{"col":-1.0,"loy":-0.5,"fam":-0.3},"ctx":{}}]},
{"id":"pro-03","by":"player","cat":"pro","q":"Would you be okay with me staying another year in junior?","elig":{"league":["CHL"]},"answers":[{"type":"strong","base":1.4,"text":"Absolutely. Go dominate, play in the World Juniors, and come in ready.","traits":{"pat":0.6,"con":0.4},"ctx":{"young":0.3}},{"type":"moderate","base":0.7,"text":"It depends on camp. If you're not ready to stick, junior is a great place to be.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"We want you to push to skip that year. Junior can get too easy for a guy like you.","traits":{"amb":1.1,"con":0.5,"pat":-0.8},"ctx":{}},{"type":"negative","base":-1.3,"text":"We're not thinking about that. We want you signed and in our system.","traits":{"pat":-0.6,"fam":-0.3},"ctx":{"young":-0.2}}]},
{"id":"pro-04","by":"gm","cat":"pro","q":"Do you see yourself staying in school all four years?","elig":{"league":["NCAA","NCAA_BOUND"]},"answers":[{"type":"strong","base":1.4,"text":"That's a perfect answer. You can do both, and we'll help you plan it.","traits":{"col":0.6,"amb":0.4,"coa":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"We'll check in every season and decide together when the time is right.","traits":{"col":0.5,"loy":0.3,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Four years is a long time. We'd want you pro in two at the most.","traits":{"amb":0.9,"col":-1.1,"pat":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"If you stay four years, we may not be the team that signs you.","traits":{"col":-0.9,"loy":-0.6,"fam":-0.3},"ctx":{}}],"reply":"I want my degree, but I also want to play in the NHL as soon as I can."},
{"id":"pro-05","by":"gm","cat":"pro","q":"Would you consider leaving college early to sign with us?","elig":{"league":["NCAA"]},"answers":[{"type":"strong","base":1.4,"text":"We'd never ask you to burn bridges. When you're ready, we'll be ready with a plan.","traits":{"col":0.6,"fam":0.5,"loy":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Fair. Let's keep talking through the season. We're in no hurry.","traits":{"pat":0.5,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"The right situation is now. A spot like this doesn't stay open forever.","traits":{"amb":1.1,"cmp":0.3,"col":-1.0,"pat":-0.5},"ctx":{}},{"type":"negative","base":-1.3,"text":"We need an answer this summer, honestly. We don't want to wait.","traits":{"col":-0.9,"pat":-0.5,"fam":-0.3},"ctx":{}}],"reply":"If the situation is right, yeah. I'd have to talk to my family and my coach."},
{"id":"pro-06","by":"player","cat":"pro","q":"Is there a chance you'd sign me right after tonight?","elig":{"age":["older"]},"answers":[{"type":"strong","base":1.4,"text":"Yes. We want to get this done this summer and have you at camp.","traits":{"amb":0.6,"con":0.4},"ctx":{"older":0.4}},{"type":"moderate","base":0.7,"text":"It's on the table. Let's get through development camp and talk numbers.","traits":{"coa":0.4,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Sign you tonight, play you next month? Slow down. Let's see the work first.","traits":{"cmp":1.0,"coa":0.3,"con":-0.7,"amb":-0.5},"ctx":{}},{"type":"negative","base":-1.3,"text":"We're not in a rush. We hold your rights for a while.","traits":{"amb":-0.8,"con":-0.5,"loy":-0.3},"ctx":{}}]},
{"id":"pro-07","by":"player","cat":"pro","q":"Do you sign your draft picks quickly or wait them out?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"We sign guys we believe in, and we believe in you. Expect a call from us soon.","traits":{"amb":0.5,"loy":0.4,"con":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"It depends on the player. With you, we'll move as fast as your development allows.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"We take our time. Some guys see that as patience, some see it as a test.","traits":{"pat":1.1,"cmp":0.4,"amb":-1.0},"ctx":{}},{"type":"negative","base":-1.3,"text":"We usually wait. There's no reason to burn contract years early.","traits":{"amb":-0.7,"loy":-0.4},"ctx":{"contend":0.2}}]},
{"id":"pro-08","by":"gm","cat":"pro","q":"Junior, college or pro next year: what's your gut telling you?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"We agree. Let's give you a pro environment and see how fast you climb.","traits":{"amb":0.6,"con":0.5},"ctx":{"older":0.3}},{"type":"moderate","base":0.7,"text":"That's a good instinct. We'll test it at camp and make the call with you.","traits":{"coa":0.5,"loy":0.2},"ctx":{}},{"type":"risky","base":0.0,"text":"Your gut and our scouts don't agree yet. Prove us wrong.","traits":{"cmp":1.2,"con":0.2,"coa":-0.4,"loy":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"Most guys who say that aren't ready. We'd rather you stay put.","traits":{"con":-0.8,"amb":-0.7},"ctx":{"young":0.2}}],"reply":"My gut says pro. I feel like I've outgrown where I am."},
{"id":"pro-09","by":"player","cat":"pro","q":"What happens if I don't make the team out of camp?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Then you go back, dominate, and we bring you up the first time someone gets hurt.","traits":{"amb":0.4,"con":0.4,"loy":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"We'll sit down with you and explain exactly what to work on. Nobody gets left in the dark.","traits":{"coa":0.6,"fam":0.2},"ctx":{}},{"type":"risky","base":0.0,"text":"Then you weren't ready. It happens to almost everyone.","traits":{"pat":0.9,"cmp":0.4,"con":-1.0,"loy":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"Then you're one of fifty guys in the system. That's just how it works.","traits":{"loy":-0.7,"con":-0.5,"fam":-0.3},"ctx":{}}]},
{"id":"pro-10","by":"player","cat":"pro","q":"Can I go to the World Juniors if I sign?","elig":{"age":["young"]},"answers":[{"type":"strong","base":1.4,"text":"Yes, a hundred percent. We'll release you, and we'll be watching every shift.","traits":{"con":0.4,"fam":0.3,"loy":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"If you're in junior, absolutely. If you're with us, we'll talk about it when it comes.","traits":{"coa":0.4,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"If you're good enough to be in the NHL, you won't be at the World Juniors. Think about that.","traits":{"amb":1.1,"con":0.3,"fam":-0.6,"loy":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"We usually don't release guys who are with the big club.","traits":{"fam":-0.6,"loy":-0.5,"con":-0.3},"ctx":{}}]},
{"id":"pro-11","by":"gm","cat":"pro","q":"Are you physically ready for men's hockey?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"It shows. You look ready, and our strength staff will take you the rest of the way.","traits":{"con":0.6,"coa":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Close is good. A summer in our program and you'll be there.","traits":{"coa":0.6,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Close isn't there. The NHL eats close for breakfast.","traits":{"cmp":1.1,"coa":0.2,"con":-0.9,"fam":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"Honestly, we think you need another year or two to fill out.","traits":{"con":-0.8,"amb":-0.6},"ctx":{"young":0.2}}],"reply":"I've put on twelve pounds this year. I think I'm close."},
{"id":"development-01","by":"player","cat":"development","q":"What does your development staff actually do with prospects?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Skills coach, strength coach, video every week and a phone call from me every month. You'll never be forgotten.","traits":{"coa":0.5,"loy":0.5},"ctx":{}},{"type":"moderate","base":0.7,"text":"Development camp, a summer plan and visits during the season. It's a real program.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"We give you the tools. What you do with them is up to you.","traits":{"cmp":1.0,"con":0.4,"coa":-0.6,"loy":-0.5},"ctx":{}},{"type":"negative","base":-1.3,"text":"Most of that is handled by the AHL staff. They'll be in touch.","traits":{"loy":-0.7,"coa":-0.4,"fam":-0.3},"ctx":{}}]},
{"id":"development-02","by":"player","cat":"development","q":"How long do guys usually spend in your AHL affiliate?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"The good ones? Half a season, maybe less. We don't let talent sit down there.","traits":{"amb":0.6,"con":0.4},"ctx":{"rebuild":0.3}},{"type":"moderate","base":0.7,"text":"It depends on the player. A year or two is normal, and it's nothing to be ashamed of.","traits":{"pat":0.6,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"As long as it takes. Some guys come up in a month, some take four years.","traits":{"pat":1.0,"amb":-1.0,"cmp":0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"Plan on two or three years. That's our model.","traits":{"amb":-0.8,"con":-0.5},"ctx":{"contend":0.2,"deep":0.2}}]},
{"id":"development-03","by":"gm","cat":"development","q":"Would you be okay spending a full year in the AHL?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's mature. You'll have a path and a timeline in writing from our development staff.","traits":{"pat":0.5,"coa":0.5,"loy":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. And if you force our hand early, we'll gladly change the plan.","traits":{"amb":0.4,"cmp":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"A full year minimum, probably more. That's the reality for most picks.","traits":{"pat":1.0,"amb":-1.1,"con":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"You might not have a choice, honestly.","traits":{"con":-0.7,"loy":-0.6,"amb":-0.4},"ctx":{}}],"reply":"If that's what it takes. I just want a clear path up."},
{"id":"development-04","by":"gm","cat":"development","q":"What's the one part of your game you know you need to fix?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"We have one of the best skating coaches in hockey. She's going to love working with you.","traits":{"coa":0.6,"amb":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Honest answer. We'll build your summer around it.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"It's more than three steps, son. It's going to take a lot of hours.","traits":{"cmp":1.0,"coa":0.4,"con":-1.0},"ctx":{}},{"type":"negative","base":-1.3,"text":"That's the thing that worries our scouts the most, honestly.","traits":{"con":-0.9,"amb":-0.4},"ctx":{}}],"reply":"My skating. My first three steps aren't where they need to be."},
{"id":"development-05","by":"player","cat":"development","q":"Will I have a say in my own development plan?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"It's your career. We build the plan with you, not for you.","traits":{"con":0.5,"loy":0.4,"coa":0.2},"ctx":{}},{"type":"moderate","base":0.7,"text":"You'll have input, and you'll know the reasons behind every decision.","traits":{"coa":0.6,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"We've done this a hundred times. Trust the process.","traits":{"coa":1.0,"pat":0.4,"con":-1.0,"amb":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"The development staff decides. That's their job.","traits":{"con":-0.8,"loy":-0.5},"ctx":{}}]},
{"id":"development-06","by":"gm","cat":"development","q":"Will you commit to our development plan, even when it's frustrating?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That trust goes both ways. We'll earn it every season.","traits":{"loy":0.6,"coa":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. Frustration is part of it. We'll talk you through the hard parts.","traits":{"coa":0.5,"pat":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"We'll see. A lot of kids say that tonight and forget it by January.","traits":{"cmp":1.0,"coa":0.3,"loy":-0.8,"con":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"You don't really have a choice once you sign.","traits":{"loy":-0.8,"con":-0.5,"fam":-0.3},"ctx":{}}],"reply":"Yes. I know it's not always going to be fun, but I trust you guys."},
{"id":"development-07","by":"player","cat":"development","q":"Do you have a good goalie coach for prospects?","elig":{"pos":["G"]},"answers":[{"type":"strong","base":1.4,"text":"One of the best in the business, and he'll be on the phone with you every week.","traits":{"coa":0.6,"loy":0.3},"ctx":{"thin":0.2}},{"type":"moderate","base":0.7,"text":"A full-time development goalie coach who visits all our goalies during the season.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Goalies have to figure it out themselves eventually. We'll give you the reps.","traits":{"con":1.0,"cmp":0.4,"coa":-0.8},"ctx":{}},{"type":"negative","base":-1.3,"text":"Our goalie coach mostly works with the NHL guys.","traits":{"loy":-0.6,"coa":-0.5,"amb":-0.3},"ctx":{}}]},
{"id":"development-08","by":"player","cat":"development","q":"If I have a big year in junior, will you bring me up sooner?","elig":{"league":["CHL"]},"answers":[{"type":"strong","base":1.4,"text":"Absolutely. Play your way onto our roster and we'll make room.","traits":{"amb":0.6,"cmp":0.4},"ctx":{"rebuild":0.3,"thin":0.3}},{"type":"moderate","base":0.7,"text":"A big year changes the conversation. We'll be watching every game.","traits":{"cmp":0.4,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"A big year in junior doesn't mean a big year here. Plenty of guys learned that the hard way.","traits":{"pat":1.0,"con":-1.0,"amb":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"The CHL rule decides that, not us. You're there until twenty either way.","traits":{"amb":-0.7,"con":-0.4},"ctx":{"young":0.2}}]},
{"id":"development-09","by":"gm","cat":"development","q":"How do you handle being sent down?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's the attitude that gets guys called back up in a week.","traits":{"cmp":0.6,"con":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. Every guy who makes it has a story about getting sent down.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Hate it quietly. Nobody up top wants to hear complaining.","traits":{"coa":1.0,"pat":0.4,"con":-0.8,"loy":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"You'll probably find out soon enough.","traits":{"con":-0.8,"loy":-0.6,"amb":-0.3},"ctx":{}}],"reply":"I'd hate it, but I'd use it. I'd go down and make it impossible to keep me there."},
{"id":"development-10","by":"player","cat":"development","q":"Do your prospects actually get better, or do they stall?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Look at our last five first-rounders. Every one of them is in the NHL.","traits":{"amb":0.5,"con":0.4,"coa":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"We've had a few stall, honestly. We changed our staff and our approach because of it.","traits":{"coa":0.5,"loy":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Prospects stall when they stop working. That's on them, not us.","traits":{"cmp":1.0,"coa":-0.6,"loy":-0.6},"ctx":{}},{"type":"negative","base":-1.3,"text":"It's hit or miss. Every team's record is like that.","traits":{"con":-0.6,"coa":-0.5,"amb":-0.4},"ctx":{}}]},
{"id":"development-11","by":"gm","cat":"development","q":"Would you be willing to play the wing if we asked?","elig":{"pos":["F"]},"answers":[{"type":"strong","base":1.4,"text":"That's the answer of a pro. Playing both makes you twice as hard to send down.","traits":{"coa":0.5,"amb":0.4},"ctx":{"thin":0.2}},{"type":"moderate","base":0.7,"text":"Good. We'll start you at center and see how camp shakes out.","traits":{"con":0.4,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"We'll probably move you to the wing full-time. Centers in this league are a different animal.","traits":{"coa":1.0,"pat":0.3,"con":-1.0},"ctx":{}},{"type":"negative","base":-1.3,"text":"We already have more centers than we need, so you'll be on the wing either way.","traits":{"con":-0.7,"amb":-0.5},"ctx":{"deep":0.3}}],"reply":"I've always been a center, but I'll play wherever gets me in the lineup."},
{"id":"direction-01","by":"player","cat":"direction","q":"Are you guys rebuilding or trying to win now?","elig":{"role":["rebuild"]},"answers":[{"type":"strong","base":1.4,"text":"We're building something, and you're one of the pieces we're building around.","traits":{"amb":0.5,"loy":0.5},"ctx":{"rebuild":0.4}},{"type":"moderate","base":0.7,"text":"We're young and getting better every year. You'll grow with this group.","traits":{"loy":0.4,"pat":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"We're rebuilding, which means losing for a while. Some guys can't handle that.","traits":{"cmp":1.0,"pat":0.6,"amb":-0.6,"con":-0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"We're rebuilding, but honestly we're still figuring out the plan.","traits":{"loy":-0.6,"con":-0.5,"coa":-0.4},"ctx":{}}]},
{"id":"direction-02","by":"player","cat":"direction","q":"Are you guys trying to win the Cup this year?","elig":{"role":["contend"]},"answers":[{"type":"strong","base":1.4,"text":"Yes, and we want young guys who can help us do it. Come to camp hungry.","traits":{"cmp":0.6,"amb":0.4},"ctx":{"contend":0.3}},{"type":"moderate","base":0.7,"text":"We are, and that means you'll learn from players who've won. That's a gift.","traits":{"coa":0.6,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"We're going for it, so there may not be room for a rookie. You'd be learning from the press box.","traits":{"pat":1.0,"amb":-1.1,"cmp":0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"Our window is now. We'll probably trade some prospects at the deadline.","traits":{"loy":-0.9,"fam":-0.4,"con":-0.3},"ctx":{}}]},
{"id":"direction-03","by":"gm","cat":"direction","q":"How do you feel about joining a team that's rebuilding?","elig":{"role":["rebuild"]},"answers":[{"type":"strong","base":1.4,"text":"Exactly. We'll give young players real roles, and you could be one of the first.","traits":{"amb":0.6,"con":0.3},"ctx":{"rebuild":0.4}},{"type":"moderate","base":0.7,"text":"It'll be tough at times, but the guys who stick through it get to win later.","traits":{"loy":0.5,"pat":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Chance to play, sure. But losing every night is hard on young guys. Are you sure?","traits":{"cmp":1.0,"pat":0.5,"con":-0.6,"amb":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"Don't get too excited. We'll bring in veterans to help shelter you.","traits":{"amb":-0.8,"con":-0.5},"ctx":{"thin":-0.2}}],"reply":"Honestly, I like it. It means a chance to play."},
{"id":"direction-04","by":"gm","cat":"direction","q":"Would you be okay waiting your turn on a contender?","elig":{"role":["contend"]},"answers":[{"type":"strong","base":1.4,"text":"Earn it, then. We've had young guys push their way into our lineup before.","traits":{"cmp":0.6,"amb":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"The wait won't be long if you work. Our veterans will make you better.","traits":{"coa":0.5,"pat":0.4,"loy":0.2},"ctx":{}},{"type":"risky","base":0.0,"text":"Waiting is the job here. Our room is full of guys who've won.","traits":{"pat":1.1,"coa":0.3,"amb":-1.1},"ctx":{}},{"type":"negative","base":-1.3,"text":"There's really no spot for a while. That's the honest truth.","traits":{"amb":-0.9,"con":-0.5},"ctx":{"deep":0.3}}],"reply":"I'd rather earn it than wait for it, but I get it. You guys are good."},
{"id":"direction-05","by":"player","cat":"direction","q":"What's the plan for this team in three years?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Contending, with you in the middle of it. That's why you're here.","traits":{"amb":0.5,"loy":0.5,"con":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Better than today, built around the young core we're adding right now.","traits":{"loy":0.4,"pat":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Hard to say. This league changes fast, and so do rosters.","traits":{"pat":0.7,"cmp":0.3,"loy":-1.0,"con":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"We're focused on this year. Three years from now is a long way off.","traits":{"loy":-0.7,"amb":-0.4},"ctx":{"contend":0.2}}]},
{"id":"direction-06","by":"player","cat":"direction","q":"Why did you pick me over the other guys on the board?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Because we think you'll be the best player in this class when it's all said and done.","traits":{"con":0.7,"amb":0.3},"ctx":{"top":0.3}},{"type":"moderate","base":0.7,"text":"Your compete level. Every scout we have came back talking about it.","traits":{"cmp":0.5,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Honestly, he went one pick before us. You were next on our list.","traits":{"cmp":1.0,"con":-1.0,"loy":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"You were the best player left. Simple as that.","traits":{"con":-0.6,"loy":-0.6},"ctx":{"late":0.2}}]},
{"id":"direction-07","by":"gm","cat":"direction","q":"What do you know about our team?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Then you know you're going to love it here. This city is going to love you back.","traits":{"loy":0.5,"fam":0.5},"ctx":{}},{"type":"moderate","base":0.7,"text":"You did your homework. That tells me a lot about you.","traits":{"coa":0.4,"con":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"The fans care a lot, which means they'll let you hear it when you struggle.","traits":{"cmp":1.0,"con":0.3,"fam":-0.6,"pat":-0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"Our fans are tough on young players. Don't read the comments.","traits":{"con":-0.7,"fam":-0.5,"loy":-0.3},"ctx":{}}],"reply":"I know you've got a great young core and fans who care a lot."},
{"id":"direction-08","by":"player","cat":"direction","q":"Will you trade me if a better deal comes along?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"You're a big part of our plans. We didn't draft you to trade you.","traits":{"loy":0.7,"fam":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Nobody's untouchable in this league, but you're about as close as a prospect gets.","traits":{"con":0.4,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Everyone has a price. Play well and you'll make that price very high.","traits":{"cmp":1.0,"con":0.3,"loy":-1.0,"fam":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"Prospects get moved all the time. That's just the business.","traits":{"loy":-0.9,"fam":-0.5},"ctx":{"contend":0.2}}]},
{"id":"direction-09","by":"gm","cat":"direction","q":"Is winning or playing time more important to you right now?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's a franchise answer. You'll be part of why we win, soon.","traits":{"cmp":0.6,"amb":0.4,"loy":0.2},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. Earn the trust and the minutes come with it.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Then get used to the press box for a bit. Our lineup wins games.","traits":{"pat":1.0,"amb":-1.1},"ctx":{"contend":0.3}},{"type":"negative","base":-1.3,"text":"Most rookies don't play a role in winning. Don't put that on yourself.","traits":{"con":-0.8,"amb":-0.5},"ctx":{}}],"reply":"Winning. But I want to be part of the reason we win."},
{"id":"direction-10","by":"player","cat":"direction","q":"Who's going to be my coach?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"A coach who loves young players. He played a nineteen-year-old on his top line last year.","traits":{"amb":0.6,"coa":0.3},"ctx":{"rebuild":0.2}},{"type":"moderate","base":0.7,"text":"A teacher. He's demanding, but every young guy who's played for him got better.","traits":{"coa":0.6,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"He's old school. Some kids love it, some don't make it through November.","traits":{"cmp":1.1,"coa":0.3,"con":-0.5,"fam":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"We're actually making a coaching change, so I can't tell you yet.","traits":{"loy":-0.6,"con":-0.4,"pat":-0.3},"ctx":{}}]},
{"id":"direction-11","by":"gm","cat":"direction","q":"If you were our GM, what would you change about this team?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Great answer. You just described yourself, and that's why we drafted you.","traits":{"con":0.6,"amb":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"We agree. That's exactly where the league is going.","traits":{"coa":0.4,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Funny. Most guys tell me they'd draft themselves earlier.","traits":{"con":1.1,"cmp":0.6,"coa":-0.6,"fam":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"Leave the GM job to me, son. You focus on your game.","traits":{"con":-0.9,"loy":-0.5},"ctx":{}}],"reply":"I'd add more speed. The game's getting faster every year."},
{"id":"depth-01","by":"player","cat":"depth","q":"How many guys are ahead of me at my position?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Fewer than you'd think. We need help at your position badly.","traits":{"amb":0.6,"cmp":0.3},"ctx":{"thin":0.5}},{"type":"moderate","base":0.7,"text":"A couple. We'll be honest with you about where you stand after camp.","traits":{"coa":0.5,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"A few, and they're good. You'll have to be better than them, period.","traits":{"cmp":1.1,"con":0.3,"pat":-0.3,"amb":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"Quite a few. Realistically, you're behind four or five guys.","traits":{"amb":-0.8,"con":-0.6},"ctx":{"deep":0.4}}]},
{"id":"depth-02","by":"player","cat":"depth","q":"Is there a spot on defense for a guy like me?","elig":{"pos":["D"]},"answers":[{"type":"strong","base":1.4,"text":"Our left side is wide open. If you can move the puck, you can play.","traits":{"amb":0.6,"con":0.4},"ctx":{"thin":0.5}},{"type":"moderate","base":0.7,"text":"We're always looking for puck-moving D. Come to camp and show us.","traits":{"cmp":0.4,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Defensemen take longer. Plenty of D-men don't stick until twenty-three.","traits":{"pat":1.1,"amb":-1.0,"con":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"Our blue line is set for the next few years.","traits":{"amb":-0.9,"con":-0.4},"ctx":{"deep":0.4,"contend":0.2}}]},
{"id":"depth-03","by":"gm","cat":"depth","q":"Would you be comfortable playing on your off side?","elig":{"pos":["D"]},"answers":[{"type":"strong","base":1.4,"text":"That's a big advantage for a young D-man. It'll get you into the lineup faster.","traits":{"amb":0.5,"coa":0.4},"ctx":{"thin":0.2}},{"type":"moderate","base":0.7,"text":"Good. We'll get you reps on both sides at camp.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"You'd probably play there full-time with us. Get comfortable with it.","traits":{"coa":1.0,"cmp":0.4,"con":-0.8},"ctx":{}},{"type":"negative","base":-1.3,"text":"That's going to be a problem with the guys we already have.","traits":{"con":-0.7,"amb":-0.5},"ctx":{"deep":0.3}}],"reply":"I've done it before. I'm more comfortable on my strong side, but I can do it."},
{"id":"depth-04","by":"gm","cat":"depth","q":"How would you feel about being a backup goalie at first?","elig":{"pos":["G"]},"answers":[{"type":"strong","base":1.4,"text":"You will be. The backup role is a step on the path, not the destination.","traits":{"amb":0.5,"loy":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Every great goalie spent time as a backup. Use it.","traits":{"pat":0.6,"coa":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Some goalies never get out of the backup role. You'll have to steal the job.","traits":{"cmp":1.1,"con":0.2,"pat":-0.3,"loy":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"You'd probably be third string in the AHL to start.","traits":{"amb":-0.9,"con":-0.6},"ctx":{"deep":0.4}}],"reply":"I'd learn a lot. But I want to be a starter one day."},
{"id":"depth-05","by":"player","cat":"depth","q":"Is your team deep at my position, or is there room?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"There's room. We didn't draft you to sit behind a crowd.","traits":{"amb":0.6,"con":0.3},"ctx":{"thin":0.4}},{"type":"moderate","base":0.7,"text":"We're decent there, but nobody's locked in. Good players find a way.","traits":{"cmp":0.5,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"We're deep. Competition makes everyone better, or it exposes them.","traits":{"cmp":1.1,"con":0.4,"pat":-0.3,"amb":-0.5},"ctx":{}},{"type":"negative","base":-1.3,"text":"We're stacked there. Honestly, you might be trade bait down the road.","traits":{"loy":-0.9,"amb":-0.5},"ctx":{"deep":0.3}}]},
{"id":"depth-06","by":"player","cat":"depth","q":"Can I play center, or am I going to the wing?","elig":{"pos":["F"]},"answers":[{"type":"strong","base":1.4,"text":"Center. That's where we see your vision helping us most.","traits":{"con":0.5,"amb":0.4},"ctx":{"thin":0.3}},{"type":"moderate","base":0.7,"text":"Both, probably. Versatility gets you to the NHL faster.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Wing. Centers have to be ready for faceoffs and defensive zone starts on day one.","traits":{"coa":1.0,"con":-1.0,"cmp":0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"We don't really see you at center at our level.","traits":{"con":-0.8,"amb":-0.5},"ctx":{"deep":0.3}}]},
{"id":"depth-07","by":"gm","cat":"depth","q":"Where do you think you fit in our lineup right now?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's a fair read. And moving up happens fast when you're good.","traits":{"con":0.5,"amb":0.4},"ctx":{"thin":0.3}},{"type":"moderate","base":0.7,"text":"That's realistic. I respect that. We'll see how camp changes it.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Third line in this league is a role, not a stepping stone. Can you kill penalties?","traits":{"cmp":1.0,"coa":0.4,"con":-0.7,"amb":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"We see you starting in the minors, to be honest.","traits":{"amb":-0.8,"con":-0.6},"ctx":{"deep":0.3,"contend":0.2}}],"reply":"Honestly? Third line, with a chance to move up."},
{"id":"depth-08","by":"player","cat":"depth","q":"Is anyone at my position close to getting traded?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"I won't say names, but you could see a spot open up before camp.","traits":{"amb":0.6,"cmp":0.3},"ctx":{"thin":0.2}},{"type":"moderate","base":0.7,"text":"Rosters always change. Stay ready.","traits":{"coa":0.4,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Maybe. Or maybe we trade you. That's hockey.","traits":{"cmp":0.9,"con":0.2,"loy":-1.0,"fam":-0.5},"ctx":{}},{"type":"negative","base":-1.3,"text":"I can't talk about that, and you shouldn't be thinking about it.","traits":{"con":-0.6,"loy":-0.5,"amb":-0.3},"ctx":{}}]},
{"id":"depth-09","by":"gm","cat":"depth","q":"What position did you play growing up?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's why you read the game so well. It's going to help you here.","traits":{"con":0.5,"coa":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"That background helps you play both ways. Coaches love that.","traits":{"coa":0.5,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"We might move you back to D someday. Would you be open to it?","traits":{"coa":0.9,"cmp":0.4,"con":-0.7,"amb":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"Interesting. That explains some of the defensive habits our scouts didn't like.","traits":{"con":-0.8,"coa":0.1},"ctx":{}}],"reply":"Defense until I was fourteen. Then my coach moved me up front."},
{"id":"depth-10","by":"player","cat":"depth","q":"Would you ever move me to defense?","elig":{"pos":["F"]},"answers":[{"type":"strong","base":1.4,"text":"No. We drafted a forward and that's where you'll play.","traits":{"con":0.5,"loy":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"We'd only talk about it if you wanted to. It'd be your call.","traits":{"con":0.4,"coa":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"If it gets you in the lineup faster, we might ask. Big forwards make good D.","traits":{"coa":1.0,"amb":0.4,"con":-0.8},"ctx":{}},{"type":"negative","base":-1.3,"text":"We haven't ruled anything out. Our forward group is crowded.","traits":{"con":-0.7,"loy":-0.4},"ctx":{"deep":0.4}}]},
{"id":"family-01","by":"player","cat":"family","q":"Can my family come to development camp?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Of course. Your family is part of this now. We'll have tickets and a hotel for them.","traits":{"fam":0.8,"loy":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Absolutely. We do a family day at the end of camp.","traits":{"fam":0.6,"coa":0.2},"ctx":{}},{"type":"risky","base":0.0,"text":"They can come, but camp is work. You'll see them at night, maybe.","traits":{"cmp":0.9,"coa":0.3,"fam":-1.0},"ctx":{}},{"type":"negative","base":-1.3,"text":"We prefer players come alone. It's easier to focus.","traits":{"fam":-1.0,"loy":-0.4},"ctx":{}}]},
{"id":"family-02","by":"gm","cat":"family","q":"Who's the biggest influence in your hockey life?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's a great story. Tell him he's welcome in our building anytime.","traits":{"fam":0.8,"loy":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Backyard rinks build players. We see it in how you handle the puck.","traits":{"fam":0.4,"con":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Good. Now you'll have pro coaches. Sometimes that's a tough handoff for dads.","traits":{"coa":1.0,"cmp":0.3,"fam":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"We'll make sure your dad knows the coaching staff makes the decisions now.","traits":{"fam":-1.0,"con":-0.4},"ctx":{}}],"reply":"My dad. He built a rink in our backyard every winter."},
{"id":"family-03","by":"player","cat":"family","q":"How far is your city from my hometown?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Close enough for your family to come to games. We'll help with that.","traits":{"fam":0.8,"loy":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"A short flight. A lot of our guys' families visit all the time.","traits":{"fam":0.6,"coa":0.2},"ctx":{}},{"type":"risky","base":0.0,"text":"Far. Moving away from home is part of growing up in this game.","traits":{"cmp":0.9,"con":0.3,"fam":-1.0,"pat":-0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"Pretty far, honestly. You'll have to get used to that.","traits":{"fam":-0.9,"loy":-0.3},"ctx":{}}]},
{"id":"family-04","by":"gm","cat":"family","q":"Have you ever lived away from home before?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's huge. You'll handle the move to pro hockey better than most.","traits":{"con":0.5,"fam":0.3,"coa":0.2},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. We'll set you up with a veteran family in town anyway.","traits":{"fam":0.6,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Living with a billet family isn't the same as being on your own in a pro city.","traits":{"cmp":0.9,"coa":0.4,"con":-0.8},"ctx":{}},{"type":"negative","base":-1.3,"text":"We'll see how that goes. Some guys struggle in their first pro year.","traits":{"con":-0.7,"fam":-0.5},"ctx":{}}],"reply":"I billeted for two years in junior. I'm used to it."},
{"id":"family-05","by":"player","cat":"family","q":"Do you help young players find somewhere to live?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Yes. We have a player services staff, and we'll put you with a veteran's family if you want.","traits":{"fam":0.7,"loy":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"We do. Housing, car, a bank account, all of it.","traits":{"fam":0.4,"coa":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"We help, but part of turning pro is figuring things out for yourself.","traits":{"con":0.9,"cmp":0.4,"fam":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"Your agent usually handles all that.","traits":{"fam":-0.8,"loy":-0.5},"ctx":{}}]},
{"id":"family-06","by":"gm","cat":"family","q":"What does your family think about you turning pro?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"We'll talk to both of them. A good plan should make your whole family comfortable.","traits":{"fam":0.8,"col":0.3,"loy":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"That's a common debate. There's no wrong answer, and we'll respect it.","traits":{"fam":0.5,"pat":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"At some point it's your decision, not theirs.","traits":{"con":1.0,"amb":0.4,"fam":-1.0},"ctx":{}},{"type":"negative","base":-1.3,"text":"We'd like your dad's answer, to be honest.","traits":{"col":-0.7,"fam":-0.5},"ctx":{"ncaa":-0.3}}],"reply":"My mom wants me to finish school first. My dad wants me in the NHL yesterday."},
{"id":"family-07","by":"player","cat":"family","q":"Is your city a good place for a young player to live?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"It's a hockey city through and through. You'll be treated like family.","traits":{"fam":0.6,"loy":0.5},"ctx":{}},{"type":"moderate","base":0.7,"text":"Great city, good restaurants, and the guys on the team all live close together.","traits":{"fam":0.4,"coa":0.2},"ctx":{}},{"type":"risky","base":0.0,"text":"It's a fishbowl. Everyone knows who you are, good night or bad.","traits":{"con":0.8,"cmp":0.4,"fam":-0.8,"pat":-0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"It's fine. You'll mostly be at the rink anyway.","traits":{"fam":-0.7,"loy":-0.4},"ctx":{}}]},
{"id":"family-08","by":"gm","cat":"family","q":"Who's here with you tonight?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Go get them. We want a picture with the whole family on stage.","traits":{"fam":0.9,"loy":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"That's great. We'll make sure they get a tour of our building this fall.","traits":{"fam":0.6,"loy":0.2},"ctx":{}},{"type":"risky","base":0.0,"text":"Enjoy tonight. Tomorrow it's all business.","traits":{"cmp":1.0,"coa":0.3,"fam":-0.8},"ctx":{}},{"type":"negative","base":-1.3,"text":"Let's keep this quick. We've got another pick to prepare for.","traits":{"fam":-0.9,"loy":-0.5,"con":-0.3},"ctx":{}}],"reply":"My parents, my grandma and my little brother. He's already wearing your hat."},
{"id":"family-09","by":"player","cat":"family","q":"Can I take time off if something happens back home?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Family comes first. Always. That's not negotiable in our organization.","traits":{"fam":0.9,"loy":0.5},"ctx":{}},{"type":"moderate","base":0.7,"text":"Of course. We've done it for plenty of players. Just talk to us.","traits":{"fam":0.6,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"We'll handle that if it comes up. Pros learn to compartmentalize.","traits":{"cmp":0.9,"con":0.3,"fam":-1.0},"ctx":{}},{"type":"negative","base":-1.3,"text":"Your schedule is your job now. We'd have to talk about it at the time.","traits":{"fam":-1.0,"loy":-0.4},"ctx":{}}]},
{"id":"family-10","by":"gm","cat":"family","q":"Do you think you can handle being far from home?","elig":{"league":["EURO"]},"answers":[{"type":"strong","base":1.4,"text":"We'll make it as easy as we can, and we've got guys from your country in our room.","traits":{"fam":0.6,"loy":0.4},"ctx":{"euro":0.3}},{"type":"moderate","base":0.7,"text":"That dream will carry you through the tough nights. We'll help with the rest.","traits":{"fam":0.4,"coa":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"The first year away breaks a lot of European kids. You need to be sure.","traits":{"cmp":1.0,"con":0.3,"fam":-0.9,"pat":-0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"We don't do much special for European players. You'll adjust.","traits":{"fam":-0.9,"loy":-0.5},"ctx":{"euro":-0.2}}],"reply":"It'll be hard. But I've wanted to play in North America since I was a kid."},
{"id":"idols-01","by":"player","cat":"idols","q":"Who do you see me playing like?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"A smaller version of a guy who just won the Hart. That's how our scouts describe you.","traits":{"con":0.6,"amb":0.4},"ctx":{"top":0.3}},{"type":"moderate","base":0.7,"text":"A two-way player who coaches trust in every situation.","traits":{"coa":0.5,"cmp":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Like yourself. We don't do comparisons. You'll have to write your own story.","traits":{"con":1.1,"cmp":0.6,"amb":-0.6,"coa":-0.5},"ctx":{}},{"type":"negative","base":-1.3,"text":"A dependable depth player. That's a compliment in this league.","traits":{"amb":-0.8,"con":-0.6},"ctx":{"late":0.3}}]},
{"id":"idols-02","by":"gm","cat":"idols","q":"Who was your favorite player growing up?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Then you know what a two-way center looks like. We see that in you.","traits":{"con":0.5,"coa":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Great player to model yourself after. We'd love to see that attention to detail.","traits":{"coa":0.6,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Lots of kids love Bergeron. Very few play like him. Show us you're one.","traits":{"cmp":1.0,"con":-0.8,"coa":0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"That's a high bar. Let's just focus on getting you to the NHL.","traits":{"con":-0.7,"amb":-0.5},"ctx":{}}],"reply":"Patrice Bergeron. I used to watch every faceoff he took."},
{"id":"idols-03","by":"gm","cat":"idols","q":"Which player in the league do you model your game after?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's the kind of puck-moving we drafted you for. Don't lose that.","traits":{"con":0.6,"amb":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good model. We'll work on the defensive side so the offense can shine.","traits":{"coa":0.6,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Everyone wants to be Makar. Most guys need to learn to defend first.","traits":{"cmp":1.0,"coa":0.4,"con":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"Let's be realistic. Nobody's Makar.","traits":{"con":-0.9,"amb":-0.6},"ctx":{}}],"reply":"Cale Makar. The way he skates the puck out of trouble."},
{"id":"idols-04","by":"player","cat":"idols","q":"Do you like an up-tempo style or a structured system?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Up-tempo. We want young legs pushing the pace, and that's you.","traits":{"amb":0.5,"con":0.4},"ctx":{"rebuild":0.2}},{"type":"moderate","base":0.7,"text":"Structured, but with freedom inside it. You'll learn it fast.","traits":{"coa":0.6,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Structured. If you can't play without the puck, you won't play.","traits":{"coa":1.0,"cmp":0.4,"con":-0.9,"amb":-0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"Our system is our system. Players adapt or they don't play.","traits":{"con":-0.8,"coa":-0.2,"loy":-0.4},"ctx":{}}]},
{"id":"idols-05","by":"gm","cat":"idols","q":"Do you see yourself as a scorer or a playmaker?","elig":{"pos":["F"]},"answers":[{"type":"strong","base":1.4,"text":"Our wingers are going to love you. We've needed a passer for years.","traits":{"con":0.5,"amb":0.4},"ctx":{"thin":0.3}},{"type":"moderate","base":0.7,"text":"That vision is why we drafted you. We'll help you add a shot.","traits":{"coa":0.6,"con":0.2},"ctx":{}},{"type":"risky","base":0.0,"text":"In this league, you shoot or you get scouted out of the play. You'll need to change that.","traits":{"coa":0.9,"cmp":0.4,"con":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"Playmakers who don't shoot don't last long.","traits":{"con":-0.9,"amb":-0.4},"ctx":{}}],"reply":"A playmaker. I'd rather make the pass than take the shot."},
{"id":"idols-06","by":"player","cat":"idols","q":"Is it okay if I play a physical game?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"We love it. Every team needs a guy the other side hates playing against.","traits":{"con":0.5,"cmp":0.4},"ctx":{"thin":0.2}},{"type":"moderate","base":0.7,"text":"Physical with discipline. Hit hard, stay out of the box.","traits":{"coa":0.6,"cmp":0.2},"ctx":{}},{"type":"risky","base":0.0,"text":"Pick your spots. Some young guys run around and get exposed.","traits":{"coa":0.9,"pat":0.4,"con":-0.8,"cmp":-0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"We'd rather you stay out of the box. Penalties kill us.","traits":{"con":-0.7,"cmp":-0.5},"ctx":{}}]},
{"id":"idols-07","by":"gm","cat":"idols","q":"What kind of goalie are you: blocker or reactive?","elig":{"pos":["G"]},"answers":[{"type":"strong","base":1.4,"text":"That's how the modern game is played. We love that about you.","traits":{"con":0.6,"amb":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. Our goalie coach will help you add some structure to it.","traits":{"coa":0.6,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Reactive goalies get beaten on rebounds at this level. You'll need to adjust.","traits":{"coa":1.0,"cmp":0.4,"con":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"Our goalie coach is going to rebuild your game from scratch.","traits":{"con":-1.0,"coa":0.1},"ctx":{}}],"reply":"Reactive. I trust my reads more than my size."},
{"id":"idols-08","by":"player","cat":"idols","q":"Did you watch me play in person?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Twelve times. I was in the building for your hat trick in the playoffs.","traits":{"con":0.6,"loy":0.5},"ctx":{}},{"type":"moderate","base":0.7,"text":"A few times, and our scouts saw you more than anyone in this class.","traits":{"con":0.4,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Once. You didn't play well that night, but we liked how you responded.","traits":{"cmp":1.0,"coa":0.4,"con":-0.8},"ctx":{}},{"type":"negative","base":-1.3,"text":"Mostly video, honestly. Our scouts handled you.","traits":{"loy":-0.8,"con":-0.4},"ctx":{}}]},
{"id":"idols-09","by":"gm","cat":"idols","q":"Who's the toughest player you've ever played against?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"And you still had points against him. That tells us everything.","traits":{"con":0.6,"cmp":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Playing against guys like him every night is what gets you ready.","traits":{"cmp":0.5,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"He's in the NHL now. You're not yet. Remember that.","traits":{"cmp":1.0,"amb":0.3,"con":-0.8,"loy":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"We saw those games. He won most of those battles.","traits":{"con":-1.0,"cmp":0.1},"ctx":{}}],"reply":"A defenseman in our league who went first overall last year. He never gave me an inch."},
{"id":"idols-10","by":"player","cat":"idols","q":"What did you guys like most about my game?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Your hockey sense. You see plays nobody else in this class sees.","traits":{"con":0.7,"amb":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Your compete and your habits away from the puck. Coaches trust that.","traits":{"coa":0.5,"cmp":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Honestly? Your upside. You're raw, but the ceiling is high.","traits":{"pat":1.0,"coa":0.5,"con":-0.8,"amb":-0.5},"ctx":{}},{"type":"negative","base":-1.3,"text":"Your size, mostly. The rest still needs a lot of work.","traits":{"con":-0.9,"amb":-0.4},"ctx":{}}]},
{"id":"work-01","by":"gm","cat":"work","q":"What does your summer training look like?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's a pro schedule already. Our strength staff will love working with you.","traits":{"cmp":0.5,"coa":0.4,"con":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. We'll send you a program so you're building the right things.","traits":{"coa":0.6,"pat":0.2},"ctx":{}},{"type":"risky","base":0.0,"text":"Six days isn't the number we care about. What you do in those days is.","traits":{"cmp":1.0,"coa":0.3,"con":-0.8},"ctx":{}},{"type":"negative","base":-1.3,"text":"We'll need to change most of that. Our program is different.","traits":{"con":-0.8,"coa":-0.2,"loy":-0.3},"ctx":{}}],"reply":"Six days a week. Gym in the morning, ice in the afternoon."},
{"id":"work-02","by":"gm","cat":"work","q":"How do you handle a bad game?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's exactly what we want. Our video coaches will be in your phone every week.","traits":{"coa":0.6,"cmp":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good habit. Just don't let one game turn into three.","traits":{"coa":0.4,"pat":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Watching it that night? Some nights you're better off sleeping. Can you let go?","traits":{"pat":1.1,"con":0.4,"cmp":-0.7,"coa":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"Bad games happen. We'll tell you what went wrong.","traits":{"con":-0.6,"coa":-0.3,"loy":-0.3},"ctx":{}}],"reply":"I watch the video that night and figure out what went wrong."},
{"id":"work-03","by":"player","cat":"work","q":"What do your prospects work on in the summer?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Whatever makes them NHL players fastest. We build a custom plan for every guy.","traits":{"amb":0.5,"coa":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Strength, skating and a skills block with our development coaches.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Whatever they want, honestly. The best ones find a way.","traits":{"con":0.9,"cmp":0.4,"coa":-0.8,"loy":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"We send everyone the same program.","traits":{"coa":-0.6,"loy":-0.5,"con":-0.3},"ctx":{}}]},
{"id":"work-04","by":"gm","cat":"work","q":"Are you willing to put on weight this summer?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"A few pounds of muscle and you'll be a different player. Our nutrition staff will take care of you.","traits":{"coa":0.6,"amb":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"We'll do it the smart way. We don't want you to lose your speed.","traits":{"coa":0.5,"con":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"You do need it. Light guys get pushed around at this level, and it shows quick.","traits":{"cmp":1.0,"coa":0.3,"con":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"If you don't, you'll have a hard time at camp.","traits":{"con":-0.8,"fam":-0.2},"ctx":{}}],"reply":"If you think I need it, I'll do it. I know I'm on the light side."},
{"id":"work-05","by":"gm","cat":"work","q":"What would your junior coach say about your work ethic?","elig":{"league":["CHL"]},"answers":[{"type":"strong","base":1.4,"text":"He did say that. We called him. That's a big reason you're here tonight.","traits":{"con":0.6,"loy":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"That's what we heard. Keep it up at our camp and the vets will notice.","traits":{"coa":0.5,"cmp":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"He also said you take some shifts off when you're tired. True?","traits":{"cmp":1.0,"coa":0.4,"con":-0.9,"loy":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"Coaches always say that about their draft picks.","traits":{"con":-0.7,"loy":-0.5},"ctx":{}}],"reply":"First guy on the ice, last guy off. He'd say that."},
{"id":"work-06","by":"player","cat":"work","q":"How hard is your development camp?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Hard, and the guys who shine there jump the line. It's your first chance to impress.","traits":{"cmp":0.6,"amb":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Tough but fair. Lots of teaching and lots of skating.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Hard enough that some guys go home early. Come in shape or don't come.","traits":{"cmp":1.1,"con":0.3,"fam":-0.4,"coa":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"It's mostly testing and meetings. You'll survive it.","traits":{"cmp":-0.6,"amb":-0.4},"ctx":{}}]},
{"id":"work-07","by":"gm","cat":"work","q":"If we asked you to work on your defensive game, how would you react?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's the most mature thing a draft pick has said to me tonight.","traits":{"coa":0.6,"con":0.3,"loy":0.2},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. Our coaches will make it the priority, and it'll pay off fast.","traits":{"coa":0.5,"amb":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"It's the thing keeping you out of our lineup, for sure. Big gap to close.","traits":{"cmp":0.9,"pat":0.4,"con":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"We'll see. Every forward says that and then cheats for offense.","traits":{"con":-0.8,"loy":-0.5},"ctx":{}}],"reply":"I'd do it. I know it's the thing keeping me out of the NHL."},
{"id":"work-08","by":"player","cat":"work","q":"How many skills coaches do you have?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Three full-time, plus a skating coach. You'll be spoiled.","traits":{"coa":0.6,"amb":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Two, and they work with prospects all year long.","traits":{"coa":0.5,"pat":0.2},"ctx":{}},{"type":"risky","base":0.0,"text":"Enough. The best skills coach is the hours you put in on your own.","traits":{"cmp":1.0,"con":0.4,"coa":-0.7},"ctx":{}},{"type":"negative","base":-1.3,"text":"One, and he's mostly with the NHL guys.","traits":{"coa":-0.7,"loy":-0.4,"amb":-0.3},"ctx":{}}]},
{"id":"work-09","by":"gm","cat":"work","q":"Are you a rink rat?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's what our scouts said. You're going to fit right in.","traits":{"cmp":0.5,"loy":0.4,"con":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. Just don't burn yourself out. Recovery matters too.","traits":{"coa":0.5,"pat":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Rink rats work hard. Pros work smart. Learn the difference.","traits":{"coa":0.9,"pat":0.4,"con":-0.8,"cmp":-0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"We'll need to manage that. Young guys overtrain all the time.","traits":{"con":-0.6,"cmp":-0.5},"ctx":{}}],"reply":"I'd sleep there if they let me."},
{"id":"work-10","by":"gm","cat":"work","q":"What's your recovery routine like?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's fine. That's our job. You'll learn more about recovery in a week with us than in five years.","traits":{"coa":0.6,"loy":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"You'll learn it at camp. It's the difference between a good season and a great one.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"You'd better start. That's how young guys end up hurt in their first pro season.","traits":{"cmp":0.9,"coa":0.4,"con":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"That worries me a little, to be honest.","traits":{"con":-0.8,"loy":-0.3},"ctx":{}}],"reply":"Honestly, I haven't thought about it much."},
{"id":"work-11","by":"player","cat":"work","q":"What separates the guys who make it from the ones who don't?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Guys like you who show up every day. That's why we took you.","traits":{"con":0.5,"loy":0.4,"cmp":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Habits. Sleep, food, video, practice. It sounds boring, but it's everything.","traits":{"coa":0.6,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Talent gets you drafted. Work keeps you here. A lot of first-rounders found that out.","traits":{"cmp":1.3,"con":-0.8,"coa":0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"Most of it is luck, honestly. Right place, right time.","traits":{"coa":-0.6,"con":-0.4,"cmp":-0.4},"ctx":{}}]},
{"id":"leadership-01","by":"gm","cat":"leadership","q":"Do you see yourself as a leader?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's the best kind of leader. Our captain is exactly the same.","traits":{"con":0.5,"loy":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. Leadership grows as you get older. You'll find your voice.","traits":{"pat":0.5,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Leading by example is great, but at some point you'll have to talk. Can you?","traits":{"cmp":1.2,"con":-0.9,"coa":0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"Leadership is for veterans. You focus on your game.","traits":{"con":-0.7,"loy":-0.4},"ctx":{}}],"reply":"I lead by example. I'm not a big talker, but I work."},
{"id":"leadership-02","by":"gm","cat":"leadership","q":"You wore the C in junior. What did that teach you?","elig":{"league":["CHL"]},"answers":[{"type":"strong","base":1.4,"text":"That's a captain's answer. Our room will respect you from day one.","traits":{"con":0.6,"loy":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"That's real experience. It'll help you in a pro room faster than you think.","traits":{"coa":0.4,"con":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"In a pro room you'll be the youngest guy again. Can you handle not being the guy?","traits":{"pat":0.9,"coa":0.4,"con":-0.9,"amb":-0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"None of that matters in our room. You start at the bottom.","traits":{"con":-0.9,"loy":-0.4},"ctx":{}}],"reply":"That the hardest part is the bad nights, when you have to stand up and say something."},
{"id":"leadership-03","by":"player","cat":"leadership","q":"Will the veterans help me, or do they freeze rookies out?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Our veterans are great with kids. Two of them asked about you this morning.","traits":{"loy":0.6,"fam":0.3,"con":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"They'll push you, but they'll help you. That's the culture we've built.","traits":{"coa":0.5,"cmp":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Some of them will, some won't. They're competing for jobs too.","traits":{"cmp":1.0,"con":0.4,"loy":-0.6,"fam":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"That's up to you. Earn their respect and they'll treat you right.","traits":{"loy":-0.6,"fam":-0.4,"con":-0.3},"ctx":{}}]},
{"id":"leadership-04","by":"gm","cat":"leadership","q":"How would your teammates describe you?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's exactly why we wanted you in our locker room.","traits":{"loy":0.7,"con":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"That's a great trait in a young player. It'll serve you well.","traits":{"loy":0.5,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Good. Now you'll be going to war against guys you grew up idolizing. Ready?","traits":{"cmp":1.0,"con":0.3,"loy":-0.3,"fam":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"Teammates always say nice things. We'll see how you are in a pro room.","traits":{"loy":-0.8,"con":-0.5},"ctx":{}}],"reply":"Loyal. I'd go to war for the guys in my room."},
{"id":"leadership-05","by":"gm","cat":"leadership","q":"What would you do if a veteran took a run at you in camp?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's the right answer. Nobody respects a guy who backs down.","traits":{"con":0.6,"cmp":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Smart. Stand up for yourself without starting a war.","traits":{"coa":0.5,"cmp":0.2},"ctx":{}},{"type":"risky","base":0.0,"text":"You'd better be ready for what comes after you answer it.","traits":{"cmp":1.0,"con":0.4,"coa":-0.5,"fam":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"You'd be better off keeping your head down.","traits":{"con":-0.8,"cmp":-0.5},"ctx":{}}],"reply":"Answer it. Respectfully, but I'd answer it."},
{"id":"leadership-06","by":"player","cat":"leadership","q":"Is there a leadership group I can learn from?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"One of the best in the league. Our captain will text you before you leave this building.","traits":{"loy":0.6,"coa":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Yes. We pair every rookie with a veteran mentor.","traits":{"coa":0.5,"fam":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"They're busy winning games. You'll learn by watching.","traits":{"pat":1.2,"coa":0.4,"loy":-0.9,"fam":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"We're actually short on leaders right now. You'd be on your own a bit.","traits":{"loy":-0.7,"con":-0.3,"fam":-0.3},"ctx":{}}]},
{"id":"leadership-07","by":"gm","cat":"leadership","q":"Can you be a leader at eighteen?","elig":{"age":["young"]},"answers":[{"type":"strong","base":1.4,"text":"We agree. We've seen it in how you carry yourself.","traits":{"con":0.6,"loy":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"That's the right mindset. Lead with your work first.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Age matters in a pro room. You'll need to read it carefully.","traits":{"coa":0.9,"pat":0.4,"con":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"At eighteen you need to listen, not lead.","traits":{"con":-0.9,"loy":-0.3},"ctx":{}}],"reply":"I think so. Age doesn't matter if you're doing things the right way."},
{"id":"leadership-08","by":"gm","cat":"leadership","q":"How do you treat the trainers and the equipment staff?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's why our scouts kept talking about you. Character matters here.","traits":{"loy":0.6,"fam":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. Those people will look after you more than anyone.","traits":{"loy":0.5,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Good answer. We'll ask them in November whether it's true.","traits":{"cmp":0.9,"coa":0.3,"con":-0.7,"loy":-0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"Everyone says that tonight.","traits":{"loy":-0.8,"con":-0.4},"ctx":{}}],"reply":"Like family. My dad always said that's how you know who a guy really is."},
{"id":"pressure-01","by":"player","cat":"pressure","q":"How much media attention would I get?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Some, and we'll help you handle it. Our PR staff trains every rookie.","traits":{"coa":0.5,"con":0.3,"fam":0.2},"ctx":{}},{"type":"moderate","base":0.7,"text":"It's a hockey market, so a fair amount. You'll get used to it fast.","traits":{"con":0.4,"cmp":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"A lot, and they'll be brutal on bad nights. Thick skin required.","traits":{"con":1.0,"cmp":0.4,"fam":-0.7,"pat":-0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"Too much, honestly. It's crushed a few young players here.","traits":{"con":-0.9,"fam":-0.5},"ctx":{}}]},
{"id":"pressure-02","by":"gm","cat":"pressure","q":"How do you handle pressure?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"We've seen it. Your playoff numbers are a big reason we took you.","traits":{"con":0.6,"cmp":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. Big games are what this organization is all about.","traits":{"cmp":0.5,"loy":0.3},"ctx":{"contend":0.2}},{"type":"risky","base":0.0,"text":"Everybody loves pressure until their first slump in a hockey market.","traits":{"pat":0.9,"coa":0.3,"con":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"We'll see. The pressure here is different from anything you've felt.","traits":{"con":-0.8,"fam":-0.3},"ctx":{}}],"reply":"I love it. The bigger the game, the better I play."},
{"id":"pressure-03","by":"gm","cat":"pressure","q":"Going this high comes with expectations. Can you handle that?","elig":{"age":["young"]},"answers":[{"type":"strong","base":1.4,"text":"It shows. You've handled everything thrown at you so far.","traits":{"con":0.6,"amb":0.3},"ctx":{"top":0.4}},{"type":"moderate","base":0.7,"text":"Good. We'll take some of that weight off you. Just play.","traits":{"fam":0.4,"coa":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"These expectations are bigger. A whole city just started counting on you.","traits":{"cmp":1.0,"con":0.2,"fam":-0.6,"pat":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"A lot of guys picked this high flamed out. Don't be one of them.","traits":{"con":-0.9,"fam":-0.3},"ctx":{}}],"reply":"I've had expectations on me since I was twelve. I'm used to it."},
{"id":"pressure-04","by":"player","cat":"pressure","q":"Do fans turn on young players when they struggle?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Not ours. They're patient with kids who work hard, and you work hard.","traits":{"fam":0.5,"loy":0.4,"con":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Every fan base gets frustrated, but they love players who care.","traits":{"loy":0.4,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Sometimes. You'll hear it. The good ones use it as fuel.","traits":{"cmp":1.0,"con":0.4,"fam":-0.6},"ctx":{}},{"type":"negative","base":-1.3,"text":"Yes. Don't read social media. Ever.","traits":{"con":-0.8,"fam":-0.5},"ctx":{}}]},
{"id":"pressure-05","by":"gm","cat":"pressure","q":"What would you do if you went pointless in your first ten games?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's the attitude. Slumps end for players who keep doing the right things.","traits":{"con":0.5,"cmp":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. We'll be there to help you look at the details.","traits":{"coa":0.6,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Ten games pointless and you'd probably be in the AHL. That's the reality.","traits":{"cmp":0.9,"pat":0.4,"con":-0.9,"amb":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"I'd be worried, honestly.","traits":{"con":-0.9,"loy":-0.4},"ctx":{}}],"reply":"Keep shooting. Keep working. It'll turn."},
{"id":"pressure-06","by":"player","cat":"pressure","q":"Is there pressure to make the team right away?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"No pressure from us. We know you'll get there, and we're patient.","traits":{"pat":0.5,"fam":0.4,"loy":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Only the pressure you put on yourself. We'll be realistic with you.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"There's always pressure on a high pick. Don't pretend there isn't.","traits":{"cmp":1.0,"con":0.4,"fam":-0.5,"pat":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"Our fans expect it, honestly. They want results.","traits":{"con":-0.8,"fam":-0.6},"ctx":{"top":0.2}}]},
{"id":"pressure-07","by":"gm","cat":"pressure","q":"How do you deal with criticism?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Exactly right. You're going to get coached hard because we believe in you.","traits":{"coa":0.6,"loy":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. Our coaches are direct, but they're fair.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Some of the criticism will be public. Ready for that?","traits":{"cmp":0.9,"con":0.4,"fam":-0.6,"coa":-0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"You'll get plenty of it here.","traits":{"con":-0.8,"loy":-0.4},"ctx":{}}],"reply":"I take it. Coaches criticize the guys they care about."},
{"id":"pressure-08","by":"player","cat":"pressure","q":"Will the media compare me to the guys picked ahead of me?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Let them. In five years, they'll be comparing those guys to you.","traits":{"con":0.7,"cmp":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"They will for a while. We don't care about that, and you shouldn't either.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Every day. You're going to be measured against them your whole career.","traits":{"cmp":1.1,"con":0.3,"fam":-0.5,"pat":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"Probably. And early on, it might not look great.","traits":{"con":-0.9},"ctx":{"late":0.2}}]},
{"id":"pressure-09","by":"gm","cat":"pressure","q":"Have you ever been booed?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's a great sign. Guys who like being booed tend to love playoff hockey.","traits":{"con":0.6,"cmp":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. You'll hear it plenty in this league.","traits":{"cmp":0.5,"coa":0.2},"ctx":{}},{"type":"risky","base":0.0,"text":"Wait until it's your own fans. That's a different feeling.","traits":{"cmp":0.9,"pat":0.3,"con":-0.7,"fam":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"Being booed in junior is a lot different from what you'll hear here.","traits":{"con":-0.8,"fam":-0.3},"ctx":{}}],"reply":"In every road rink in the league. I kind of like it."},
{"id":"europe-01","by":"player","cat":"europe","q":"Can I stay in Europe another year before coming over?","elig":{"league":["EURO"]},"answers":[{"type":"strong","base":1.4,"text":"Absolutely. Playing against men in your league is great development. We'll watch closely.","traits":{"pat":0.6,"fam":0.5},"ctx":{"euro":0.4}},{"type":"moderate","base":0.7,"text":"We'd like you here soon, but another year at home is fine if it's the right step.","traits":{"fam":0.4,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"We want you in North America now. The small rink takes adjusting, and the sooner the better.","traits":{"amb":1.1,"cmp":0.3,"fam":-0.8,"pat":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"If you stay, someone else might take your spot in our plans.","traits":{"fam":-0.8,"loy":-0.6},"ctx":{"euro":-0.2}}]},
{"id":"europe-02","by":"gm","cat":"europe","q":"Are you ready to play on a smaller rink?","elig":{"league":["EURO"]},"answers":[{"type":"strong","base":1.4,"text":"It suited you. Our scouts saw you at the World Juniors and you looked comfortable.","traits":{"con":0.6,"amb":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"It takes a few months. We'll give you time to adjust.","traits":{"pat":0.5,"coa":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Some European players never adjust. You'll need to be quicker with decisions.","traits":{"cmp":1.0,"coa":0.4,"con":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"We're worried about that, honestly.","traits":{"con":-0.9,"amb":-0.4},"ctx":{}}],"reply":"I think so. I've played some international games on NHL ice."},
{"id":"europe-03","by":"player","cat":"europe","q":"Will you help me learn English and settle in?","elig":{"league":["EURO"]},"answers":[{"type":"strong","base":1.4,"text":"Yes. A tutor, a host family and two teammates who speak your language.","traits":{"fam":0.7,"loy":0.4},"ctx":{"euro":0.3}},{"type":"moderate","base":0.7,"text":"We have a player services team that handles everything for European players.","traits":{"fam":0.5,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Most guys pick it up fast. The locker room is the best teacher.","traits":{"con":0.8,"cmp":0.4,"fam":-0.8},"ctx":{}},{"type":"negative","base":-1.3,"text":"Your agent usually takes care of that.","traits":{"fam":-0.8,"loy":-0.5},"ctx":{}}]},
{"id":"europe-04","by":"gm","cat":"europe","q":"Would you consider playing in the AHL instead of back home?","elig":{"league":["EURO"]},"answers":[{"type":"strong","base":1.4,"text":"It is, and it's the fastest path to our lineup. We'd love to have you there.","traits":{"amb":0.6,"cmp":0.3},"ctx":{"thin":0.2}},{"type":"moderate","base":0.7,"text":"We'll decide together. Both paths can work for you.","traits":{"fam":0.4,"coa":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"The AHL is long bus rides and a lot of hockey. It's not for everybody.","traits":{"cmp":1.0,"con":0.3,"fam":-0.7,"pat":-0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"You'd probably be a depth player there at first.","traits":{"amb":-0.8,"con":-0.5},"ctx":{}}],"reply":"Maybe. I've heard the AHL is a hard league. I want to be close to the NHL."},
{"id":"europe-05","by":"player","cat":"europe","q":"Do you have other players from my country on the team?","elig":{"league":["EURO"]},"answers":[{"type":"strong","base":1.4,"text":"Three of them, and they've already asked when you're coming.","traits":{"fam":0.7,"loy":0.4},"ctx":{"euro":0.3}},{"type":"moderate","base":0.7,"text":"One in the NHL and one in the AHL. You won't be alone.","traits":{"fam":0.5,"coa":0.2},"ctx":{}},{"type":"risky","base":0.0,"text":"Not right now. You'd be the first in a while. Some guys like that.","traits":{"con":0.9,"cmp":0.4,"fam":-0.8},"ctx":{}},{"type":"negative","base":-1.3,"text":"No. You'll have to adapt on your own.","traits":{"fam":-0.9,"loy":-0.4},"ctx":{}}]},
{"id":"europe-06","by":"gm","cat":"europe","q":"What does your club back home want you to do?","elig":{"league":["EURO"]},"answers":[{"type":"strong","base":1.4,"text":"We'll work with them. A good relationship with your club helps everyone.","traits":{"fam":0.5,"loy":0.5,"pat":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"That's a compliment to you. Let's weigh it together.","traits":{"pat":0.4,"coa":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Your club wants what's good for your club. We want what's good for your career.","traits":{"amb":1.0,"con":0.3,"loy":-0.8,"fam":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"If you re-sign there, we may lose interest.","traits":{"loy":-0.9,"fam":-0.5},"ctx":{}}],"reply":"They want me to stay. They've offered me a bigger role and a new contract."},
{"id":"europe-07","by":"player","cat":"europe","q":"Will I lose my rights if I stay in Europe too long?","elig":{"league":["EURO"]},"answers":[{"type":"strong","base":1.4,"text":"We hold your rights for years. Take the time you need, and we'll be in touch every month.","traits":{"pat":0.6,"loy":0.4,"fam":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"You've got a few years. We'll make a plan before that becomes an issue.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Eventually, yes. Don't make us wait until the last minute.","traits":{"cmp":0.9,"amb":0.4,"loy":-0.7,"fam":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"If you're not here in two years, honestly, we'll move on.","traits":{"loy":-0.9,"fam":-0.4,"pat":-0.3},"ctx":{}}]},
{"id":"europe-08","by":"gm","cat":"europe","q":"Why do you want to play in the NHL?","elig":{"league":["EURO"]},"answers":[{"type":"strong","base":1.4,"text":"That's what we want to hear. You're going to find out you're very good.","traits":{"con":0.6,"cmp":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good reason. Come over when you're ready and we'll show you.","traits":{"pat":0.4,"fam":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"You'll find out fast. Some guys don't like the answer.","traits":{"cmp":1.0,"con":0.3,"fam":-0.5,"pat":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"Plenty of guys say that, then go home after a year.","traits":{"con":-0.8,"loy":-0.4,"fam":-0.3},"ctx":{}}],"reply":"Because it's the best league in the world. I want to know how good I really am."},
{"id":"europe-09","by":"gm","cat":"europe","q":"Are you comfortable with the North American schedule?","elig":{"league":["EURO"]},"answers":[{"type":"strong","base":1.4,"text":"It shows. Your conditioning numbers were the best of the Europeans we tested.","traits":{"con":0.6,"coa":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"It takes a season to get used to. We'll manage your workload.","traits":{"coa":0.5,"pat":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"A lot of European rookies hit a wall in January. You'll need to push through.","traits":{"cmp":1.0,"coa":0.3,"con":-0.8},"ctx":{}},{"type":"negative","base":-1.3,"text":"That worries us a bit, honestly.","traits":{"con":-0.8,"amb":-0.4},"ctx":{}}],"reply":"Eighty-two games is a lot. But I've been training for it."},
{"id":"contract-01","by":"player","cat":"contract","q":"When would you want to sign my entry-level deal?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"This summer, if you're ready. We'd love to get it done before camp.","traits":{"amb":0.6,"con":0.4},"ctx":{"older":0.3}},{"type":"moderate","base":0.7,"text":"When it makes sense for your development. We'll talk with your agent soon.","traits":{"coa":0.4,"pat":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"When you show us you're ready. The contract is the easy part.","traits":{"cmp":1.0,"con":-0.8,"amb":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"There's no rush. We hold your rights for a while.","traits":{"amb":-0.8,"loy":-0.5},"ctx":{}}]},
{"id":"contract-02","by":"gm","cat":"contract","q":"Has your agent talked to you about an entry-level deal?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"He's right. The timing is now, if you want it.","traits":{"amb":0.6,"con":0.3},"ctx":{"older":0.3}},{"type":"moderate","base":0.7,"text":"Exactly. We'll work out the right moment together.","traits":{"coa":0.4,"pat":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Timing is everything. Sign too early and you burn a year of your deal.","traits":{"pat":0.9,"coa":0.4,"amb":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"We'll talk to your agent when we're ready.","traits":{"loy":-0.7,"con":-0.4},"ctx":{}}],"reply":"A little. He says the money is pretty standard, so it's more about timing."},
{"id":"contract-03","by":"player","cat":"contract","q":"Would signing early burn a year of my contract?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Not if you play under ten games. The slide rule protects you, and we'll explain it all.","traits":{"coa":0.5,"pat":0.4,"con":0.2},"ctx":{}},{"type":"moderate","base":0.7,"text":"It might, but we'd only do it if you're ready to play here.","traits":{"amb":0.4,"coa":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Probably. That's the price of being in a hurry.","traits":{"pat":0.9,"cmp":0.3,"amb":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"That's your agent's job to figure out.","traits":{"loy":-0.7,"coa":-0.4},"ctx":{}}]},
{"id":"contract-04","by":"gm","cat":"contract","q":"Do you want to sign tonight, or take the summer?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Then let's make it happen. We'll have papers ready before you leave.","traits":{"amb":0.6,"loy":0.5},"ctx":{"older":0.3}},{"type":"moderate","base":0.7,"text":"We love that. Let's do it the right way, with your agent and your family.","traits":{"fam":0.4,"coa":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Tonight's emotional. Sleep on it. We want a commitment you mean.","traits":{"pat":1.0,"coa":0.3,"amb":-0.8,"con":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"We're not ready to offer anything tonight.","traits":{"amb":-0.9,"loy":-0.6},"ctx":{}}],"reply":"I want to sign. I don't want there to be any question I'm all in."},
{"id":"contract-05","by":"player","cat":"contract","q":"Are the bonuses in my deal going to be fair?","elig":{"age":["older"]},"answers":[{"type":"strong","base":1.4,"text":"Absolutely. We use the max bonuses for guys we believe in.","traits":{"con":0.5,"amb":0.4},"ctx":{"top":0.4}},{"type":"moderate","base":0.7,"text":"We'll be fair. Your agent will see the full structure this week.","traits":{"coa":0.4,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Bonuses are earned. Hit the numbers and you get paid.","traits":{"cmp":1.1,"con":0.3,"loy":-0.5},"ctx":{}},{"type":"negative","base":-1.3,"text":"Bonuses depend on where you were picked. Yours will be modest.","traits":{"con":-0.8,"loy":-0.4},"ctx":{"late":0.3}}]},
{"id":"contract-06","by":"gm","cat":"contract","q":"What matters more to you: signing now or staying where you are?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Then let's make you a pro. We'll get your agent on the phone tomorrow.","traits":{"amb":0.6,"con":0.4},"ctx":{"older":0.3}},{"type":"moderate","base":0.7,"text":"Good. We'll make sure it's the right step at the right time.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Being a pro means sometimes you sign and still go back. Are you okay with that?","traits":{"pat":1.2,"coa":0.4,"amb":-1.0},"ctx":{}},{"type":"negative","base":-1.3,"text":"Let's not rush. You're not ready yet in our eyes.","traits":{"amb":-0.9,"con":-0.6},"ctx":{}}],"reply":"Signing. I want to be a pro."},
{"id":"contract-07","by":"player","cat":"contract","q":"Can I sign and still go back to junior if needed?","elig":{"league":["CHL"]},"answers":[{"type":"strong","base":1.4,"text":"Yes. You'd sign, come to camp and we'd decide together. Junior is a safety net, not a step back.","traits":{"pat":0.5,"coa":0.4,"fam":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"That's how it works for most guys your age. Totally normal.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"You can, but most guys who sign and go back lose a year on their deal.","traits":{"pat":1.0,"amb":-0.8,"cmp":0.4,"con":-0.5},"ctx":{}},{"type":"negative","base":-1.3,"text":"We'd only sign you if you're making the team.","traits":{"amb":-0.7,"pat":-0.4},"ctx":{"young":0.2}}]},
{"id":"contract-08","by":"gm","cat":"contract","q":"Would you sign a two-way deal to start?","elig":{"age":["older"]},"answers":[{"type":"strong","base":1.4,"text":"It's just paperwork. If you play well, it won't matter where you start.","traits":{"con":0.4,"amb":0.4,"coa":0.2},"ctx":{}},{"type":"moderate","base":0.7,"text":"Right. It protects both of us while you develop.","traits":{"coa":0.5,"pat":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"It means you'll probably start in the minors. Be ready for that.","traits":{"pat":1.2,"cmp":0.5,"amb":-1.0},"ctx":{}},{"type":"negative","base":-1.3,"text":"That's all we're going to offer.","traits":{"amb":-0.8,"loy":-0.5,"con":-0.3},"ctx":{}}],"reply":"Sure. I know that's how it works for most guys."},
{"id":"contract-09","by":"player","cat":"contract","q":"What happens to my rights if I go to college?","elig":{"league":["NCAA","NCAA_BOUND"]},"answers":[{"type":"strong","base":1.4,"text":"We keep them while you're in school, and we'll be at your games. No pressure, no deadlines.","traits":{"col":0.8,"pat":0.4,"fam":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"We hold them for four years. That gives you plenty of room.","traits":{"col":0.5,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"We hold them, but if you stay all four years, you could walk as a free agent. Think about that.","traits":{"amb":0.8,"col":-1.0,"loy":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"If you stay too long, we'll probably trade your rights.","traits":{"col":-0.9,"loy":-0.6,"fam":-0.3},"ctx":{}}]},
{"id":"contract-10","by":"gm","cat":"contract","q":"Is there any reason you wouldn't sign with us?","elig":{"league":["NCAA","NCAA_BOUND"]},"answers":[{"type":"strong","base":1.4,"text":"We'd never make you choose. Finish school, and the contract will be waiting.","traits":{"col":0.9,"fam":0.6,"loy":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"We understand. We'll find a plan that works for your family.","traits":{"fam":0.6,"col":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"We hear you, but every year in school is a year you're not with us.","traits":{"amb":0.9,"col":-1.1,"fam":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"That's going to make this hard.","traits":{"col":-1.0,"fam":-0.6},"ctx":{}}],"reply":"Only if it meant giving up on finishing school. That matters to my family."},
{"id":"character-01","by":"gm","cat":"character","q":"What do you do when you're not playing hockey?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Ha. Half our room plays the same games. You'll fit right in.","traits":{"fam":0.5,"loy":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. You need something to switch your brain off.","traits":{"pat":0.4,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Fishing's fine. Watch the video games during the season. Sleep matters.","traits":{"coa":1.0,"cmp":0.3,"con":-0.7,"fam":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"At this level, hockey has to be your whole life.","traits":{"fam":-0.8,"con":-0.4},"ctx":{}}],"reply":"Fishing with my brothers. And video games, honestly."},
{"id":"character-02","by":"gm","cat":"character","q":"Is there anything in your background we should know about?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's what everyone told us. Your character references were the best in the class.","traits":{"con":0.5,"loy":0.5},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good. We did our homework, and we believe you.","traits":{"loy":0.4,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"We know about the suspension last year. Tell us about it yourself.","traits":{"coa":0.9,"cmp":0.3,"con":-0.9,"loy":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"We'll find out either way.","traits":{"loy":-0.9,"con":-0.5},"ctx":{}}],"reply":"No. I've never been in any trouble."},
{"id":"character-03","by":"player","cat":"character","q":"Do you care about what kind of person I am off the ice?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"More than anything. That's why we spent an hour with your coaches and your teachers.","traits":{"loy":0.6,"fam":0.5},"ctx":{}},{"type":"moderate","base":0.7,"text":"Absolutely. We want good people in our room, not just good players.","traits":{"loy":0.5,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"We care how you play. Off the ice is your business, as long as you're professional.","traits":{"con":1.0,"cmp":0.4,"loy":-0.8,"fam":-0.7},"ctx":{}},{"type":"negative","base":-1.3,"text":"Honestly, we care about the hockey.","traits":{"loy":-0.8,"fam":-0.5},"ctx":{}}]},
{"id":"character-04","by":"gm","cat":"character","q":"How do you give back to your community?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's amazing. Our foundation would love to have you involved.","traits":{"fam":0.5,"loy":0.5},"ctx":{}},{"type":"moderate","base":0.7,"text":"That says a lot about you. Keep it up.","traits":{"loy":0.4,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"You'll have a lot less free time as a pro. You'll need to choose.","traits":{"cmp":0.9,"coa":0.3,"fam":-0.8},"ctx":{}},{"type":"negative","base":-1.3,"text":"That's nice, but your summers belong to your training now.","traits":{"fam":-0.9,"loy":-0.4},"ctx":{}}],"reply":"I coach a learn-to-skate program back home every summer."},
{"id":"character-05","by":"gm","cat":"character","q":"What's the hardest thing you've been through?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"And you came back better. That's exactly the resilience we were looking for.","traits":{"con":0.6,"loy":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"That's tough. Our medical staff is one of the best, if anything ever happens again.","traits":{"fam":0.4,"coa":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Injuries change some guys. Our doctors will want to take a close look.","traits":{"cmp":0.9,"coa":0.3,"con":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"Our medical team flagged that, honestly.","traits":{"con":-0.9,"loy":-0.4},"ctx":{}}],"reply":"I broke my leg at sixteen and missed a whole season."},
{"id":"character-06","by":"player","cat":"character","q":"What kind of people work in your front office?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"People who'll know your name, your family's names and your birthday. We're a family.","traits":{"loy":0.6,"fam":0.6},"ctx":{}},{"type":"moderate","base":0.7,"text":"Smart, honest people. We'll always tell you the truth.","traits":{"coa":0.5,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Busy people. You'll mostly deal with the development staff.","traits":{"cmp":0.8,"con":0.4,"loy":-0.8,"fam":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"It's a business. People come and go.","traits":{"loy":-0.9,"fam":-0.5},"ctx":{}}]},
{"id":"character-07","by":"gm","cat":"character","q":"What's one thing your coaches don't know about you?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Ha! Bring the notebook to camp. We want to see it get a lot fuller.","traits":{"con":0.5,"fam":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"That's a great habit. Shows you care about the details.","traits":{"coa":0.4,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Goals are great. Write down your plus-minus too.","traits":{"cmp":1.0,"coa":0.4,"con":-0.8},"ctx":{}},{"type":"negative","base":-1.3,"text":"That's a little strange, but okay.","traits":{"con":-0.8,"fam":-0.3},"ctx":{}}],"reply":"I write down every goal I've ever scored in a notebook."},
{"id":"character-08","by":"player","cat":"character","q":"Do you guys mind if I'm a bit of a character in the room?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"We love it. Every winning room has a guy who keeps it loose.","traits":{"con":0.6,"loy":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"As long as you're working, have fun. That's the deal.","traits":{"coa":0.4,"cmp":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Read the room first. Rookies who talk too much get humbled fast.","traits":{"coa":1.0,"pat":0.4,"con":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"Keep your head down your first year.","traits":{"con":-0.8,"loy":-0.3,"fam":-0.2},"ctx":{}}]},
{"id":"character-09","by":"gm","cat":"character","q":"What would you do if you weren't playing hockey?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Smart kid. That brain is a big part of how you read the game.","traits":{"con":0.5,"fam":0.4,"col":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good to have a plan. But we think you'll be playing for a long time.","traits":{"col":0.4,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Engineering? You might have to choose sooner than you think.","traits":{"amb":0.9,"col":-1.0,"fam":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"Let's hope it doesn't come to that.","traits":{"con":-0.8,"fam":-0.3},"ctx":{}}],"reply":"Probably go to school for engineering. My mom's an engineer."},
{"id":"character-10","by":"gm","cat":"character","q":"Who would you call first after tonight?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Tell him we said thank you. We're going to keep that relationship going.","traits":{"loy":0.6,"fam":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good choice. Loyalty like that is rare.","traits":{"loy":0.5,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Your junior coach is history now. Your new coaches are the ones who matter.","traits":{"coa":0.9,"cmp":0.4,"loy":-1.0,"fam":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"Call your agent first. We have things to discuss.","traits":{"loy":-0.9,"fam":-0.5},"ctx":{}}],"reply":"My junior coach. He's the reason I'm here."},
{"id":"character-11","by":"player","cat":"character","q":"Is it okay to be nervous right now?","elig":{"age":["young"]},"answers":[{"type":"strong","base":1.4,"text":"Totally. I was nervous on my first day here too. Enjoy every second of it.","traits":{"fam":0.5,"loy":0.4,"pat":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Of course. Everyone on that stage tonight is nervous.","traits":{"fam":0.4,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Be nervous tonight. By camp, we need you ready to go.","traits":{"cmp":1.0,"coa":0.3,"fam":-0.5,"pat":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"Nerves are a sign you're not ready. Work on that.","traits":{"con":-0.9,"fam":-0.4},"ctx":{}}]},
{"id":"character-12","by":"gm","cat":"character","q":"How do you want to be remembered as a player?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"That's the kind of player who wins Cups. We're going to love having you.","traits":{"loy":0.6,"con":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"That's a great goal. Start with your linemates at camp.","traits":{"coa":0.5,"cmp":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Making others better is great. Making yourself better comes first.","traits":{"cmp":1.0,"amb":0.4,"loy":-0.6,"coa":-0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"Let's worry about making the team first.","traits":{"con":-0.8,"amb":-0.4},"ctx":{}}],"reply":"As a guy who made everyone around him better."},
{"id":"pro-12","by":"player","cat":"pro","q":"Would you be upset if I played all four years of college?","elig":{"league":["NCAA","NCAA_BOUND"]},"answers":[{"type":"strong","base":1.4,"text":"Not at all. Some of the best players in this league did four years. We'll be at every game.","traits":{"col":0.8,"pat":0.4,"loy":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"We'd rather have you sooner, but we'll respect whatever you and your coaches decide.","traits":{"col":0.5,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Upset? No. But four years is a long time to watch other guys take your spot.","traits":{"amb":0.9,"cmp":0.3,"col":-1.0},"ctx":{}},{"type":"negative","base":-1.3,"text":"Honestly, yes. Players who stay four years usually don't sign.","traits":{"col":-1.0,"loy":-0.6},"ctx":{}}]},
{"id":"pro-13","by":"gm","cat":"pro","q":"What do your college coaches want for you?","elig":{"league":["NCAA","NCAA_BOUND"]},"answers":[{"type":"strong","base":1.4,"text":"That sounds like a great plan. A big year there makes your jump easier.","traits":{"col":0.7,"pat":0.5,"loy":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"We'll talk to them. We want to work with your coaches, not against them.","traits":{"col":0.4,"coa":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Being a top-line college player is great, but our top line is a lot harder.","traits":{"amb":1.0,"cmp":0.3,"col":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"College coaches always want their best players back. Don't let that decide for you.","traits":{"col":-0.9,"loy":-0.5,"fam":-0.2},"ctx":{}}],"reply":"They want me back next year to be a top-line guy and maybe captain."},
{"id":"pro-14","by":"player","cat":"pro","q":"Is the college hockey route respected in your organization?","elig":{"league":["NCAA","NCAA_BOUND"]},"answers":[{"type":"strong","base":1.4,"text":"Very much. Half our development staff played college hockey, including me.","traits":{"col":0.8,"loy":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Absolutely. Some of our best players came through college.","traits":{"col":0.5,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"It's respected, but we like guys who are in a hurry.","traits":{"amb":0.9,"cmp":0.4,"col":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"We prefer junior, honestly. More games, more pro-style schedule.","traits":{"col":-1.0,"loy":-0.4},"ctx":{"ncaa":0.2}}]},
{"id":"pro-15","by":"gm","cat":"pro","q":"If a pro offer came after your first college season, would you take it?","elig":{"league":["NCAA","NCAA_BOUND"]},"answers":[{"type":"strong","base":1.4,"text":"Then let's get you ready. We'll be in touch with your college staff all year.","traits":{"amb":0.6,"coa":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Good to know. We'll stay in close contact and decide together.","traits":{"coa":0.4,"pat":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Don't decide yet. Take the year, see how it feels.","traits":{"pat":0.9,"col":0.4,"amb":-0.8},"ctx":{}},{"type":"negative","base":-1.3,"text":"We'll see if you're worth an offer by then.","traits":{"con":-0.9,"loy":-0.5},"ctx":{}}],"reply":"Probably, if the team thought I was ready."},
{"id":"direction-12","by":"player","cat":"direction","q":"Are you trying to win the Cup next season?","elig":{"role":["contend"]},"answers":[{"type":"strong","base":1.4,"text":"Yes, and a young player who can give us energy minutes might be a big piece of it.","traits":{"amb":0.6,"cmp":0.4},"ctx":{"contend":0.3}},{"type":"moderate","base":0.7,"text":"We're close. You'd get to learn from a team that expects to win.","traits":{"coa":0.5,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"We're trying to win now. Prospects aren't a priority this season.","traits":{"pat":1.2,"con":0.4,"amb":-1.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"Honestly, rookies don't really play on teams like ours.","traits":{"amb":-0.8,"con":-0.6},"ctx":{"deep":0.2}}]},
{"id":"direction-13","by":"gm","cat":"direction","q":"You know we're retooling. Does that bother you?","elig":{"role":["retool"]},"answers":[{"type":"strong","base":1.4,"text":"Exactly. That's why you're here. We want young players to take spots.","traits":{"amb":0.6,"con":0.4},"ctx":{"thin":0.2}},{"type":"moderate","base":0.7,"text":"There will be opportunities. We'll be honest with you about where you stand.","traits":{"coa":0.4,"loy":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"There will be spots. There'll also be a lot of guys fighting for them.","traits":{"cmp":1.1,"con":0.4,"pat":-0.5,"loy":-0.5},"ctx":{}},{"type":"negative","base":-1.3,"text":"We're still figuring out what we are. Hard to make promises.","traits":{"con":-0.8,"loy":-0.5},"ctx":{}}],"reply":"No. It sounds like there might be a spot for a young guy."},
{"id":"pressure-10","by":"gm","cat":"pressure","q":"Have you ever played in front of a sold-out crowd?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Then you're ready for our building. Every night feels like that here.","traits":{"con":0.6,"amb":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"That's great experience. It helps when you get to the big stage.","traits":{"coa":0.4,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"World Juniors is one tournament. Our building does it forty-one nights a year.","traits":{"cmp":1.0,"con":-0.7,"pat":0.2},"ctx":{}},{"type":"negative","base":-1.3,"text":"We noticed you struggled a bit at that tournament.","traits":{"con":-0.9,"loy":-0.4},"ctx":{}}],"reply":"At the World Juniors. Nineteen thousand. I'll never forget it."},
{"id":"pressure-11","by":"player","cat":"pressure","q":"What if I struggle my first season?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Then we'll fix it together. We've drafted you for the next fifteen years, not fifteen games.","traits":{"loy":0.6,"pat":0.4,"fam":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"Everyone struggles. We'll give you the tools and the time.","traits":{"coa":0.5,"pat":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"Then you go down and fix it. That's what the AHL is for.","traits":{"cmp":0.9,"pat":0.4,"amb":-0.8,"con":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"That's on you. We expect results.","traits":{"con":-0.9,"loy":-0.5,"fam":-0.3},"ctx":{}}]},
{"id":"work-12","by":"player","cat":"work","q":"Do you track how hard players work?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Yes, and guys who outwork everyone get rewarded here. Ask our captain.","traits":{"cmp":0.6,"amb":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"We track everything: sleep, workload, skating numbers. It helps you get better.","traits":{"coa":0.6,"pat":0.2},"ctx":{}},{"type":"risky","base":0.0,"text":"We track it all. If you're coasting, we'll know.","traits":{"cmp":1.0,"con":0.3,"fam":-0.4,"coa":-0.4},"ctx":{}},{"type":"negative","base":-1.3,"text":"We don't really have time to micromanage prospects.","traits":{"coa":-0.7,"loy":-0.4},"ctx":{}}]},
{"id":"leadership-09","by":"player","cat":"leadership","q":"Can I wear my junior number?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"It's yours. We already checked with the equipment manager.","traits":{"loy":0.5,"con":0.4,"fam":0.3},"ctx":{}},{"type":"moderate","base":0.7,"text":"We'll make it happen, if it's open when you make the team.","traits":{"loy":0.4,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Numbers are earned around here. Take what we give you for now.","traits":{"cmp":1.0,"coa":0.4,"con":-0.8,"loy":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"That number is retired, so you'll need a new one.","traits":{"loy":-0.7,"fam":-0.4},"ctx":{}}]},
{"id":"family-11","by":"gm","cat":"family","q":"Will your family come to your games?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"They'll have tickets for every home game. We want them around.","traits":{"fam":0.7,"loy":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"We'll take care of them when they visit. Family matters to us.","traits":{"fam":0.5,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Pro hockey is a little different. You'll have to grow up on your own.","traits":{"con":0.9,"cmp":0.3,"fam":-1.0},"ctx":{}},{"type":"negative","base":-1.3,"text":"That's a long drive. You might not see them as much.","traits":{"fam":-0.9,"loy":-0.3},"ctx":{}}],"reply":"Every one they can. My parents have driven to every road game since peewee."},
{"id":"family-12","by":"player","cat":"family","q":"Can my billet family come to camp?","elig":{"league":["CHL"]},"answers":[{"type":"strong","base":1.4,"text":"Absolutely. Bring them to the scrimmage. We'll set up seats.","traits":{"fam":0.6,"loy":0.5},"ctx":{}},{"type":"moderate","base":0.7,"text":"Sure. We'll give them a call this week.","traits":{"fam":0.4,"coa":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Camp's a business trip. Keep the focus on hockey.","traits":{"cmp":1.0,"con":0.3,"fam":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"Probably not. It's a closed camp.","traits":{"fam":-0.8,"loy":-0.4},"ctx":{}}]},
{"id":"europe-10","by":"gm","cat":"europe","q":"Would you move over here if your family couldn't come?","elig":{"league":["EURO"]},"answers":[{"type":"strong","base":1.4,"text":"We'll make it easier. Flights home at Christmas, and your family can visit anytime.","traits":{"fam":0.7,"loy":0.4},"ctx":{"euro":0.3}},{"type":"moderate","base":0.7,"text":"We'll help you settle. Lots of players have done it, and we'll be there for you.","traits":{"fam":0.4,"coa":0.4},"ctx":{}},{"type":"risky","base":0.0,"text":"It's lonely at first. Some guys handle it and some don't.","traits":{"con":0.9,"cmp":0.4,"fam":-0.9},"ctx":{}},{"type":"negative","base":-1.3,"text":"That's part of the job. Everyone goes through it.","traits":{"fam":-0.9,"loy":-0.4},"ctx":{}}],"reply":"It would be hard, but yes. This is my dream."},
{"id":"contract-11","by":"gm","cat":"contract","q":"What would it take for you to sign this summer?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"There's a plan, and it has your name on it. We'll walk you through every step.","traits":{"coa":0.5,"loy":0.5,"pat":0.2},"ctx":{}},{"type":"moderate","base":0.7,"text":"Fair. We'll put it in writing with your agent this week.","traits":{"coa":0.4,"con":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"The plan is: show up and play well. The rest takes care of itself.","traits":{"cmp":1.0,"con":0.4,"coa":-0.7},"ctx":{}},{"type":"negative","base":-1.3,"text":"Every player has the same plan at first.","traits":{"loy":-0.8,"con":-0.5},"ctx":{}}],"reply":"Knowing there's a real plan for me. Not just a contract."},
{"id":"contract-12","by":"player","cat":"contract","q":"Would you give me a bonus if I make the team out of camp?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Absolutely. Make the team and you'll be paid like it.","traits":{"amb":0.6,"con":0.4},"ctx":{"top":0.3}},{"type":"moderate","base":0.7,"text":"Bonuses are standard in entry-level deals. We'll make yours fair.","traits":{"coa":0.4,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"The bonus is making the team. That's what you should be chasing.","traits":{"cmp":1.0,"con":-0.6,"amb":-0.3},"ctx":{}},{"type":"negative","base":-1.3,"text":"Bonuses are for proven players.","traits":{"amb":-0.8,"con":-0.5},"ctx":{}}]},
{"id":"character-13","by":"gm","cat":"character","q":"Who's the funniest guy on your junior team?","elig":{"league":["CHL"]},"answers":[{"type":"strong","base":1.4,"text":"Good! Our room needs a guy like that.","traits":{"con":0.5,"fam":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"That's great. Keep it light, but keep working.","traits":{"coa":0.4,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Funny's great until you're a minus-three. Be careful.","traits":{"cmp":1.0,"coa":0.3,"con":-0.8},"ctx":{}},{"type":"negative","base":-1.3,"text":"Our room is pretty serious. Keep that in mind.","traits":{"con":-0.8,"fam":-0.4},"ctx":{}}],"reply":"Probably me, honestly."},
{"id":"idols-11","by":"player","cat":"idols","q":"Did you ever watch me play?","elig":{},"answers":[{"type":"strong","base":1.4,"text":"Every scout we have watched you, and so did I. Twice in person.","traits":{"con":0.6,"loy":0.4},"ctx":{}},{"type":"moderate","base":0.7,"text":"Yes. I was there for your playoff run. You were great.","traits":{"con":0.4,"loy":0.3},"ctx":{}},{"type":"risky","base":0.0,"text":"Video, mostly. You'll have to show me in person.","traits":{"cmp":1.0,"coa":0.3,"con":-0.8},"ctx":{}},{"type":"negative","base":-1.3,"text":"Honestly, no. I trust my scouts.","traits":{"con":-0.8,"loy":-0.6},"ctx":{}}]}
];
